const fmtDate=d=>d?new Intl.DateTimeFormat('nl-NL',{weekday:'short',day:'numeric',month:'short'}).format(new Date(d+'T12:00:00')):'–';
const fmtLong=d=>d?new Intl.DateTimeFormat('nl-NL',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(d+'T12:00:00')):'–';
const initials=name=>String(name||'?').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
const number=v=>Number.isFinite(Number(v))?Number(v):0;
const presentStatus=s=>!!s&&String(s).startsWith('Aanwezig');
const absentStatus=s=>!!s&&!presentStatus(s);
