function defaultTeam(){return state.teams?.[0]||null}
function activeTeam(){return state.teams.find(t=>t.id===ui.teamId)||defaultTeam()}
function teamName(id){return state.teams.find(t=>t.id===id)?.name||'Geen team'}
function playerById(id){return state.players.find(p=>p.id===id)}
function exerciseById(id){return state.exercises.find(e=>e.id===id)}
function trainingById(id){return state.trainings.find(t=>t.id===id)}
function matchById(id){return state.matches.find(m=>m.id===id)}
function tacticById(id){return state.tactics.find(t=>t.id===id)}
function eventById(id){return trainingById(id)||matchById(id)}
function eventType(ev){if(!ev)return 'Activiteit';return state.trainings.some(x=>x.id===ev.id)?'Training':'Wedstrijd'}
function playersForTeam(teamId){return state.players.filter(p=>p.active!==false&&p.primaryTeamId===teamId).sort((a,b)=>a.name.localeCompare(b.name,'nl'))}
function availablePlayersForTeam(teamId){return state.players.filter(p=>p.active!==false&&(p.teamIds||[]).includes(teamId)).sort((a,b)=>a.name.localeCompare(b.name,'nl'))}
function eventSquad(ev){const ids=Array.isArray(ev?.squadPlayerIds)&&ev.squadPlayerIds.length?ev.squadPlayerIds:null;return ids?ids.map(playerById).filter(p=>p&&p.active!==false):playersForTeam(ev?.teamId||activeTeam()?.id)}
function eventPlayerIds(ev){return eventSquad(ev).map(p=>p.id)}
function eventAttendanceCounts(ev){const ids=eventPlayerIds(ev),vals=ids.map(id=>ev.attendance?.[id]||'');return {total:ids.length,filled:vals.filter(Boolean).length,present:vals.filter(presentStatus).length,absent:vals.filter(absentStatus).length,unknown:vals.filter(v=>!v).length}}
function combinedSchedule(teamId=ui.teamId){return [
  ...state.trainings.filter(x=>!teamId||x.teamId===teamId).map(x=>({...x,type:'Training'})),
  ...state.matches.filter(x=>!teamId||x.teamId===teamId).map(x=>({...x,type:'Wedstrijd'})),
  ...(state.seasonItems||[]).filter(x=>!teamId||!x.teamId||x.teamId===teamId)
].sort((a,b)=>a.date.localeCompare(b.date)||(a.startTime||'').localeCompare(b.startTime||''))}
function nextTraining(teamId=ui.teamId){return state.trainings.filter(t=>(!teamId||t.teamId===teamId)&&t.date>=TODAY()).sort((a,b)=>a.date.localeCompare(b.date))[0]||null}
function latestTraining(teamId=ui.teamId){return state.trainings.filter(t=>(!teamId||t.teamId===teamId)&&t.date<=TODAY()).sort((a,b)=>b.date.localeCompare(a.date))[0]||null}
function nextMatch(teamId=ui.teamId){return state.matches.filter(m=>(!teamId||m.teamId===teamId)&&m.date>=TODAY()).sort((a,b)=>a.date.localeCompare(b.date))[0]||null}
function attendancePct(playerId,teamId=ui.teamId){const past=state.trainings.filter(t=>(!teamId||t.teamId===teamId)&&t.date<=TODAY()&&t.attendance&&t.attendance[playerId]);if(!past.length)return null;return Math.round(past.filter(t=>presentStatus(t.attendance[playerId])).length/past.length*100)}
function matchTotals(playerId,teamId=ui.teamId){let games=0,starts=0,minutes=0,goals=0,assists=0,yellow=0,red=0;state.matches.filter(m=>!teamId||m.teamId===teamId).forEach(m=>{const s=m.playerStats?.[playerId];if(s){games++;starts+=s.started?1:0;minutes+=number(s.minutes);goals+=number(s.goals);assists+=number(s.assists);yellow+=number(s.yellow);red+=number(s.red)}});return {games,starts,minutes,goals,assists,yellow,red}}
function statusBadge(status){if(!status)return '<span class="badge">Niet ingevuld</span>';const c=presentStatus(status)?'green':status.includes('blessure')||status.includes('ziek')?'red':status.includes('vakantie')||status.includes('school')?'orange':'';return `<span class="badge ${c}">${esc(status)}</span>`}
function teamOptions(selected){return state.teams.map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${esc(t.name)}</option>`).join('')}
function attendanceOptions(selected){return STATUSES.map(s=>`<option value="${esc(s)}" ${s===selected?'selected':''}>${s||'Niet ingevuld'}</option>`).join('')}
function formationOptions(selected='4-3-3'){return Object.keys(FORMATIONS).map(f=>`<option ${f===selected?'selected':''}>${f}</option>`).join('')}
function monthLabel(key){return new Intl.DateTimeFormat('nl-NL',{month:'long',year:'numeric'}).format(new Date(key+'-01T12:00:00'))}

function normalize(){
  state=state||clone(window.STARTER_DATA||{});state.version=2;state.meta??={};state.team??={name:'Full Speed O23',season:'2026/2027',trainingTime:'20:00'};
  state.players??=[];state.trainings??=[];state.matches??=[];state.exercises??=[];state.tactics??=[];state.seasonItems??=[];state.teams??=[];state.coachNotes??=[];state.documents??=[];state.settings??={};state.ai??={endpoint:'',modelLabel:'Lokale coachassistent'};
  if(!state.teams.length){const id='team-'+(state.team.name||'team').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');state.teams=[{id,name:state.team.name||'Team',shortName:'O23',category:'',active:true,formation:'4-3-3',notes:''}]}
  const first=state.teams[0].id;
  state.players.forEach(p=>{p.primaryTeamId??=first;p.teamIds=Array.isArray(p.teamIds)&&p.teamIds.length?p.teamIds:[p.primaryTeamId||first];if(!p.teamIds.includes(p.primaryTeamId))p.teamIds.unshift(p.primaryTeamId);p.alternatePositions??=[];p.preferredFoot??='';p.birthDate??='';p.active??=true;p.developmentGoals??='';p.scores??={technical:0,tactical:0,physical:0,mental:0,attitude:0};Object.keys(SCORE_LABELS).forEach(k=>p.scores[k]??=0);p.conversations??=[];p.notes??='';p.selection??='Overig';p.position??='';p.number??=''});
  state.exercises.forEach(e=>{e.coachPoints??=[];e.goal??='';e.organization??='';e.size??='';e.materials??='';e.variations??='';e.sourceDocId??=null;e.tags??=[];e.duration??=10;e.category??='Overig';e.players??='';e.intensity??='Middel';e.description??=''});
  state.trainings.forEach(t=>{t.teamId??=first;t.squadPlayerIds??=null;t.attendance??={};t.intensity??='Middel';t.load??='';t.coachNotes??='';t.planItems??=(t.exerciseIds||[]).map((eid,i)=>{const ex=exerciseById(eid);return {id:`pi-${t.id}-${i}`,exerciseId:eid,duration:ex?.duration||10,coachPoints:clone(ex?.coachPoints||[]),notes:''}});t.exerciseIds=t.planItems.map(x=>x.exerciseId)});
  state.matches.forEach(m=>{m.teamId??=first;m.squadPlayerIds??=null;m.attendance??={};m.lineup??={};m.benchIds??=[];m.playerStats??={};m.goalsFor??='';m.goalsAgainst??='';m.formation??='4-3-3';m.competition??='';m.venue??='';m.notes??='';m.plan??={teamGoal:'',pressing:'',buildUp:'',setPieces:'',individual:''};m.evaluation??={good:'',improve:'',nextTraining:''};m.checklist??={selection:false,lineup:false,opponent:false,setPieces:false,warmup:false,materials:false};Object.keys(CHECKLIST_LABELS).forEach(k=>m.checklist[k]??=false)});
  state.tactics.forEach(t=>{t.teamId??=first;t.board??={objects:[]};t.board.objects??=[];t.points??=[];t.roleNotes??={};t.formation??='4-3-3'});
  state.periodization??={matchDay:'Zaterdag',principles:'',weeklyTemplate:[]};
  if(!ui.teamId||!state.teams.some(t=>t.id===ui.teamId))ui.teamId=first;
}
function load(){try{const raw=localStorage.getItem(STORAGE_KEY)||localStorage.getItem(LEGACY_STORAGE_KEY);state=raw?JSON.parse(raw):clone(window.STARTER_DATA);normalize();if(!localStorage.getItem(STORAGE_KEY))save({render:false,sync:false})}catch{state=clone(window.STARTER_DATA);normalize()}}
function save({render=true,sync=true}={}){state.meta.updatedAt=new Date().toISOString();localStorage.setItem(STORAGE_KEY,JSON.stringify(state));const lbl=$('#saveStateLabel');if(lbl)lbl.textContent='Opgeslagen '+new Date().toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'});if(render)renderPage();if(sync&&syncConfigured()){clearTimeout(syncTimer);syncTimer=setTimeout(()=>pushSync(true),1200)}}
function toast(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function setPage(page){
  ui.page=page;
  const activeNavPage=page==='player'?'players':page;
  $$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===activeNavPage));
  renderPage();
  window.scrollTo({top:0,behavior:'smooth'});
}
function pageInfo(){
  if(ui.page==='player'){
    const p=playerById(ui.playerId);
    return [p?.name||'Speler','SPELERSprofiel'];
  }
  const map={dashboard:['Vandaag','OVERZICHT'],players:['Teams & spelers','SELECTIE & ONTWIKKELING'],attendance:['Aanwezigheid','BESCHIKBAARHEID'],trainings:['Trainingen','PLANNING & COACHPUNTEN'],exercises:['Oefeningen','BIBLIOTHEEK'],matches:['Wedstrijden','OPSTELLING & EVALUATIE'],tactics:['Tactiekbord','SPELIDEE'],season:['Seizoen','KALENDER & PERIODISERING'],stats:['Statistieken','TEAM & SPELERS'],notes:['Coachnotities','OBSERVATIES'],documents:['Bronnen','DOCUMENTEN → OEFENINGEN'],assistant:['Coachassistent','SLIMME COACHHULP'],settings:['Instellingen','APP & SYNC'],more:['Meer','FOOTBALL COACH']};
  return map[ui.page]||map.dashboard;
}
function renderTeamSelect(){const s=$('#globalTeamSelect');if(!s)return;s.innerHTML=teamOptions(ui.teamId);s.value=ui.teamId;s.onchange=()=>{ui.teamId=s.value;ui.attendanceId=null;ui.trainingId=null;ui.matchId=null;renderPage()};$('#brandTeam').textContent=activeTeam()?.name||state.team.name||'Football Coach'}
function renderPage(){normalize();const [title,eye]=pageInfo();$('#pageTitle').textContent=title;$('#pageEyebrow').textContent=(state.team.season?`SEIZOEN ${state.team.season} · `:'')+eye;renderTeamSelect();const fn={dashboard:renderDashboard,players:renderPlayers,player:renderPlayerProfilePage,attendance:renderAttendance,trainings:renderTrainings,exercises:renderExercises,matches:renderMatches,tactics:renderTactics,season:renderSeason,stats:renderStats,notes:renderNotes,documents:renderDocuments,assistant:renderAssistant,settings:renderSettings,more:renderMore}[ui.page]||renderDashboard;$('#app').innerHTML=fn();bindPage()}
function scheduleRow(e){
  const d=new Date(e.date+'T12:00:00');
  const title=e.type==='Wedstrijd'?(e.opponent?`vs ${e.opponent}`:'Wedstrijd'):(e.title||'Training');
  const inner=`<div class="date-box"><strong>${d.getDate()}</strong><span>${d.toLocaleDateString('nl-NL',{month:'short'})}</span></div><div><strong>${esc(title)}</strong><div class="event-meta"><span class="muted small">${fmtDate(e.date)} ${esc(e.startTime||'')}</span>${e.focus?`<span class="chip">${esc(e.focus)}</span>`:''}</div></div><span class="badge ${e.type==='Training'?'green':'blue'}">${esc(e.type||'Activiteit')}</span>`;
  if(e.type==='Training')return `<button type="button" class="schedule-row schedule-link" data-open-schedule-training="${e.id}">${inner}</button>`;
  if(e.type==='Wedstrijd')return `<button type="button" class="schedule-row schedule-link" data-open-schedule-match="${e.id}">${inner}</button>`;
  return `<div class="schedule-row">${inner}</div>`;
}
function renderDashboard(){
  const team=activeTeam(),players=playersForTeam(team.id),nt=nextTraining(),nm=nextMatch(),lt=latestTraining();const ac=lt?eventAttendanceCounts(lt):{present:0,absent:0};
  const low=players.map(p=>({p,pct:attendancePct(p.id)})).filter(x=>x.pct!==null&&x.pct<75).sort((a,b)=>a.pct-b.pct).slice(0,5);
  const upcoming=combinedSchedule().filter(e=>e.date>=TODAY()).slice(0,7);const notes=state.coachNotes.filter(n=>!n.teamId||n.teamId===team.id).sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,3);
  return `<div class="grid kpis">
    <div class="card kpi"><span>Spelers in ${esc(team.shortName||team.name)}</span><strong>${players.length}</strong><span>${players.filter(p=>p.selection==='Definitief').length} definitief · ${players.filter(p=>p.selection==='Twijfel').length} twijfel</span></div>
    <div class="card kpi"><span>Laatste training</span><strong>${ac.present}</strong><span>aanwezig · ${ac.absent} afwezig</span></div>
    <div class="card kpi"><span>Volgende wedstrijd</span><strong>${nm?new Date(nm.date+'T12:00:00').getDate():'–'}</strong><span>${nm?`${fmtDate(nm.date)} · ${esc(nm.opponent||'tegenstander')}`:'Nog niet gepland'}</span></div>
    <div class="card kpi"><span>Oefeningen</span><strong>${state.exercises.length}</strong><span>${state.documents.length} bron${state.documents.length===1?'':'nen'} geïmporteerd</span></div>
  </div>
  <div class="grid two">
    <section class="card"><div class="card-head"><div><p class="eyebrow">KOMENDE DAGEN</p><h2>Planning</h2></div><button class="btn secondary small-btn" data-go="season">Seizoen</button></div>${upcoming.length?upcoming.map(scheduleRow).join(''):'<div class="empty">Geen activiteiten gepland.</div>'}</section>
    <section class="card"><div class="card-head"><div><p class="eyebrow">VOLGENDE TRAINING</p><h2>${nt?fmtLong(nt.date):'Nog plannen'}</h2></div>${nt?`<span class="badge green">${esc(nt.startTime||state.team.trainingTime||'20:00')}</span>`:''}</div>
      ${nt?`<p class="muted">${esc(nt.focus||'Nog geen trainingsfocus ingesteld.')}</p><div class="list"><div class="list-row"><span>Groep</span><strong>${eventSquad(nt).length} spelers</strong></div><div class="list-row"><span>Trainingsplan</span><strong>${nt.planItems.length} oefeningen · ${nt.planItems.reduce((a,x)=>a+number(x.duration),0)} min</strong></div><div class="list-row"><span>Aanwezigheid ingevuld</span><strong>${eventAttendanceCounts(nt).filled}/${eventSquad(nt).length}</strong></div></div><div style="margin-top:16px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" data-attendance="${nt.id}">Aanwezigheid</button><button class="btn ghost" data-training-open="${nt.id}">Training openen</button></div>`:'<button class="btn primary" data-add-training>Training plannen</button>'}
    </section>
  </div>
  <div class="grid two" style="margin-top:16px">
    <section class="card"><div class="card-head"><div><p class="eyebrow">AANDACHT</p><h2>Spelers onder 75% opkomst</h2></div><button class="btn ghost small-btn" data-go="stats">Statistieken</button></div>${low.length?low.map(x=>`<div class="list-row"><span>${esc(x.p.name)}</span><strong class="${x.pct<60?'danger-text':''}">${x.pct}%</strong></div>`).join(''):'<div class="empty">Geen spelers onder 75% op basis van ingevulde trainingen.</div>'}</section>
    <section class="card"><div class="card-head"><div><p class="eyebrow">COACHNOTITIES</p><h2>Laatste observaties</h2></div><button class="btn ghost small-btn" data-go="notes">Alle notities</button></div>${notes.length?notes.map(n=>`<div class="note-card"><div class="note-meta"><span class="badge">${fmtDate(n.date)}</span>${n.playerId?`<span class="chip green">${esc(playerById(n.playerId)?.name||'Speler')}</span>`:''}</div><div class="small">${nl2br(n.text)}</div></div>`).join(''):'<div class="empty">Nog geen coachnotities.</div>'}</section>
  </div>`
}

function renderPlayers(){
  const team=activeTeam(),q=ui.playerSearch.toLowerCase();const players=playersForTeam(team.id).filter(p=>!q||[p.name,p.position,p.selection,(p.alternatePositions||[]).join(' ')].join(' ').toLowerCase().includes(q));
  const teamTabs=state.teams.map(t=>`<button class="team-tab ${t.id===team.id?'active':''}" data-team-tab="${t.id}">${esc(t.name)} <span class="tiny">${playersForTeam(t.id).length}</span></button>`).join('');
  return `<div class="toolbar"><div class="left"><div class="team-tabs">${teamTabs}</div></div><div class="right"><button class="btn ghost" data-add-team>＋ Team</button><button class="btn primary" data-add-player>＋ Speler</button></div></div>
  <div class="grid two"><section class="card"><div class="card-head"><div><p class="eyebrow">TEAM</p><h2>${esc(team.name)}</h2><p class="muted small">${esc(team.category||'')} · voorkeursformatie ${esc(team.formation||'4-3-3')}</p></div><button class="btn ghost small-btn" data-edit-team="${team.id}">Team bewerken</button></div><div class="grid three"><div class="summary-box"><span class="small muted">Spelers</span><strong>${playersForTeam(team.id).length}</strong></div><div class="summary-box"><span class="small muted">Definitief</span><strong>${playersForTeam(team.id).filter(p=>p.selection==='Definitief').length}</strong></div><div class="summary-box"><span class="small muted">Twijfel</span><strong>${playersForTeam(team.id).filter(p=>p.selection==='Twijfel').length}</strong></div></div>${team.notes?`<p class="small muted" style="margin-top:12px">${nl2br(team.notes)}</p>`:''}</section>
  <section class="card"><div class="card-head"><div><p class="eyebrow">SNEL</p><h2>Groep beheren</h2></div></div><p class="muted small">Een speler kan in meerdere teams staan. Het primaire team verschijnt op zijn profiel; trainingen kunnen daarnaast een eigen selectie/groep gebruiken.</p><div class="callout">Aanwezigheid gebruikt automatisch de spelers van het gekozen team, tenzij je bij een training of wedstrijd een eigen groep selecteert.</div></section></div>
  <div class="toolbar" style="margin-top:16px"><div class="left"><input id="playerSearch" class="input" placeholder="Zoek speler, positie of status..." value="${esc(ui.playerSearch)}"></div><div class="right"><span class="muted small">${players.length} spelers zichtbaar</span></div></div>
  <section class="card"><div class="table-wrap"><table class="players-table"><thead><tr><th>Speler</th><th>Positie</th><th>Primair team</th><th>Selectie</th><th>Opkomst</th><th>Wedstrijdmin.</th><th></th></tr></thead><tbody>${players.map(p=>{const pct=attendancePct(p.id,team.id),mt=matchTotals(p.id,team.id);return `<tr><td><button class="link-button player-name" data-profile-player="${p.id}">${esc(p.name)}</button></td><td>${esc(p.position||'–')}${p.alternatePositions?.length?`<div class="muted tiny">${esc(p.alternatePositions.join(', '))}</div>`:''}</td><td>${esc(teamName(p.primaryTeamId))}</td><td><span class="badge ${p.selection==='Definitief'?'green':p.selection==='Twijfel'?'orange':''}">${esc(p.selection||'Overig')}</span></td><td>${pct===null?'–':`<strong>${pct}%</strong><div class="progress"><span style="width:${pct}%"></span></div>`}</td><td>${mt.minutes}</td><td><div class="row-actions"><button class="btn ghost small-btn" data-edit-player="${p.id}">Bewerk</button><button class="btn ghost small-btn" data-profile-player="${p.id}">Profiel</button><button class="btn danger small-btn" data-archive-player="${p.id}">Uit selectie</button></div></td></tr>`}).join('')}</tbody></table></div></section>`
}
function teamForm(t={}){return `<div class="form-grid"><div class="field full"><label>Teamnaam</label><input id="fTeamName" class="input" value="${esc(t.name||'')}"></div><div class="field"><label>Korte naam</label><input id="fTeamShort" class="input" value="${esc(t.shortName||'')}"></div><div class="field"><label>Categorie</label><input id="fTeamCat" class="input" placeholder="O23 / 1e / Vrouwen 1" value="${esc(t.category||'')}"></div><div class="field"><label>Voorkeursformatie</label><select id="fTeamFormation">${formationOptions(t.formation||'4-3-3')}</select></div><div class="field"><label>Actief</label><select id="fTeamActive"><option value="1" ${t.active!==false?'selected':''}>Ja</option><option value="0" ${t.active===false?'selected':''}>Nee</option></select></div><div class="field full"><label>Notities</label><textarea id="fTeamNotes">${esc(t.notes||'')}</textarea></div></div>`}
function editTeam(id){const t=id?state.teams.find(x=>x.id===id):null;modal(t?'Team bewerken':'Team toevoegen',teamForm(t||{}),()=>{const name=$('#fTeamName').value.trim();if(!name){toast('Vul een teamnaam in');return false}const obj=t||{id:uid('team')};Object.assign(obj,{name,shortName:$('#fTeamShort').value.trim(),category:$('#fTeamCat').value.trim(),formation:$('#fTeamFormation').value,active:$('#fTeamActive').value==='1',notes:$('#fTeamNotes').value.trim()});if(!t){state.teams.push(obj);ui.teamId=obj.id}return true})}
function playerForm(p={}){const ids=p.teamIds||[ui.teamId];const s=p.scores||{};return `<div class="form-grid"><div class="field full"><label>Naam</label><input id="fName" class="input" value="${esc(p.name||'')}"></div><div class="field"><label>Rugnummer</label><input id="fNumber" class="input" inputmode="numeric" value="${esc(p.number||'')}"></div><div class="field"><label>Positie</label><input id="fPosition" class="input" placeholder="CV / RB / 6 / 8 / 10..." value="${esc(p.position||'')}"></div><div class="field"><label>Alternatieve posities</label><input id="fAltPositions" class="input" placeholder="RB, CVM" value="${esc((p.alternatePositions||[]).join(', '))}"></div><div class="field"><label>Voorkeursbeen</label><select id="fFoot"><option value=""></option><option ${p.preferredFoot==='Rechts'?'selected':''}>Rechts</option><option ${p.preferredFoot==='Links'?'selected':''}>Links</option><option ${p.preferredFoot==='Tweebenig'?'selected':''}>Tweebenig</option></select></div><div class="field"><label>Geboortedatum</label><input id="fBirth" class="input" type="date" value="${esc(p.birthDate||'')}"></div><div class="field"><label>Selectiestatus</label><select id="fSelection">${['Definitief','Twijfel','O19/O23','Eerste elftal','Geblesseerd','Tijdelijk niet beschikbaar','Overig'].map(x=>`<option ${p.selection===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Primair team</label><select id="fPrimaryTeam">${teamOptions(p.primaryTeamId||ui.teamId)}</select></div><div class="field full"><label>Teams waarin speler beschikbaar is</label><div class="check-grid">${state.teams.map(t=>`<label class="check-item"><input type="checkbox" name="playerTeam" value="${t.id}" ${ids.includes(t.id)?'checked':''}> ${esc(t.name)}</label>`).join('')}</div></div><div class="field full"><label>Ontwikkeldoelen</label><textarea id="fGoals">${esc(p.developmentGoals||'')}</textarea></div><div class="field full"><label>Coachnotities speler</label><textarea id="fNotes">${esc(p.notes||'')}</textarea></div><div class="field full"><label>Ontwikkelscores (0 = niet beoordeeld, 1–5)</label><div class="score-grid">${Object.entries(SCORE_LABELS).map(([k,l])=>`<div class="field"><label>${l}</label><input id="score-${k}" class="input" type="number" min="0" max="5" value="${number(s[k])}"></div>`).join('')}</div></div></div>`}
function editPlayer(id){
  const p=id?playerById(id):null;
  modal(p?'Spelerprofiel bewerken':'Speler toevoegen',playerForm(p||{}),()=>{
    const name=$('#fName').value.trim();
    if(!name){toast('Vul een naam in');return false}
    const teamIds=$$('input[name=playerTeam]:checked').map(x=>x.value);
    const primary=$('#fPrimaryTeam').value;
    if(!teamIds.includes(primary))teamIds.unshift(primary);
    const obj=p||{id:uid('p'),conversations:[],active:true};
    Object.assign(obj,{
      name,
      number:$('#fNumber').value.trim(),
      position:$('#fPosition').value.trim(),
      alternatePositions:$('#fAltPositions').value.split(',').map(x=>x.trim()).filter(Boolean),
      preferredFoot:$('#fFoot').value,
      birthDate:$('#fBirth').value,
      selection:$('#fSelection').value,
      primaryTeamId:primary,
      teamIds,
      developmentGoals:$('#fGoals').value.trim(),
      notes:$('#fNotes').value.trim(),
      scores:Object.fromEntries(Object.keys(SCORE_LABELS).map(k=>[k,Math.max(0,Math.min(5,number($(`#score-${k}`).value))) ]))
    });
    if(!p)state.players.push(obj);
    return true;
  })
}
function showPlayerProfile(id){
  const p=playerById(id);
  if(!p)return;
  ui.playerId=id;
  setPage('player');
}
function renderPlayerProfilePage(){
  const p=playerById(ui.playerId);
  if(!p){
    return `<section class="card"><div class="empty">Speler niet gevonden.</div><button class="btn ghost" data-go="players" style="margin-top:12px">← Terug naar spelers</button></section>`;
  }
  const teamId=p.primaryTeamId||ui.teamId;
  const pct=attendancePct(p.id,teamId);
  const mt=matchTotals(p.id,teamId);
  const teams=(p.teamIds||[]).map(teamName).filter(Boolean);
  const notes=state.coachNotes.filter(n=>n.playerId===p.id).sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,8);
  const scoreBoxes=Object.entries(SCORE_LABELS).map(([key,label])=>`<div class="player-development-score"><span>${label}</span><strong>${number(p.scores?.[key])||'–'}</strong><small>/ 5</small></div>`).join('');
  return `
    <div class="player-profile-actions">
      <button class="btn ghost" data-go="players">← Team</button>
      <div class="row-actions">
        <button class="btn danger" data-archive-player="${p.id}">Uit selectie</button>
        <button class="btn primary" data-edit-player="${p.id}">✎ Bewerken</button>
      </div>
    </div>
    <div class="player-profile-layout">
      <aside class="card player-profile-summary">
        <div class="player-profile-avatar">${initials(p.name)}</div>
        <div class="player-profile-name">
          <p class="eyebrow">SPELER</p>
          <h2>${esc(p.name)}</h2>
          <p class="muted">${esc(p.position||'Positie niet ingevuld')}</p>
        </div>
        <div class="chips player-profile-tags">
          <span class="badge green">${esc(teamName(p.primaryTeamId))}</span>
          ${p.number?`<span class="badge">#${esc(p.number)}</span>`:''}
          <span class="badge ${p.selection==='Definitief'?'green':p.selection==='Twijfel'?'orange':''}">${esc(p.selection||'Overig')}</span>
        </div>
        <div class="player-info-list">
          <div><span>Positie</span><strong>${esc(p.position||'–')}</strong></div>
          <div><span>Alternatief</span><strong>${p.alternatePositions?.length?esc(p.alternatePositions.join(', ')):'–'}</strong></div>
          <div><span>Voorkeursbeen</span><strong>${esc(p.preferredFoot||'–')}</strong></div>
          <div><span>Geboortedatum</span><strong>${p.birthDate?fmtLong(p.birthDate):'–'}</strong></div>
          <div><span>Teams</span><strong>${teams.length?teams.map(esc).join(', '):'–'}</strong></div>
        </div>
      </aside>
      <main class="player-profile-main">
        <div class="player-profile-stats">
          <div class="card player-stat-card"><span>Opkomst</span><strong>${pct===null?'–':pct+'%'}</strong><small>Trainingen</small></div>
          <div class="card player-stat-card"><span>Wedstrijden</span><strong>${mt.games}</strong><small>${mt.starts} basis</small></div>
          <div class="card player-stat-card"><span>Minuten</span><strong>${mt.minutes}</strong><small>Wedstrijdminuten</small></div>
          <div class="card player-stat-card"><span>Goals / assists</span><strong>${mt.goals} / ${mt.assists}</strong><small>Dit seizoen</small></div>
        </div>
        <section class="card">
          <div class="card-head"><div><p class="eyebrow">ONTWIKKELING</p><h2>Spelersontwikkeling</h2></div></div>
          <div class="player-development-grid">${scoreBoxes}</div>
        </section>
        <section class="card">
          <div class="card-head"><div><p class="eyebrow">DOELSTELLINGEN</p><h2>Ontwikkeldoelen</h2></div></div>
          ${p.developmentGoals?`<div class="callout">${nl2br(p.developmentGoals)}</div>`:`<div class="empty">Nog geen ontwikkeldoelen ingevuld.</div>`}
        </section>
        <section class="card">
          <div class="card-head"><div><p class="eyebrow">COACH</p><h2>Spelersnotities</h2></div></div>
          ${p.notes?`<div class="callout">${nl2br(p.notes)}</div>`:`<p class="muted small">Geen vaste spelersnotities.</p>`}
        </section>
        <section class="card">
          <div class="card-head"><div><p class="eyebrow">OBSERVATIES</p><h2>Recente coachnotities</h2></div><button class="btn ghost small-btn" data-go="notes">Alle notities</button></div>
          ${notes.length?notes.map(n=>`<div class="note-card"><div class="note-meta"><span class="badge">${fmtDate(n.date)}</span><span class="chip">${esc(n.category||'Notitie')}</span></div><div class="small">${nl2br(n.text)}</div></div>`).join(''):`<div class="empty">Nog geen coachnotities voor deze speler.</div>`}
        </section>
      </main>
    </div>`;
}

function renderAttendance(){
  const team=activeTeam();
  const events=state.trainings
    .filter(x=>x.teamId===team.id)
    .map(x=>({...x,_type:'Training'}))
    .sort((a,b)=>b.date.localeCompare(a.date));

  const selected=trainingById(ui.attendanceId);
  if(!ui.attendanceId||!selected||selected.teamId!==team.id){
    ui.attendanceId=(events.find(e=>e.date===TODAY())||events[0])?.id||null;
  }

  const ev=trainingById(ui.attendanceId);
  if(!ev)return `<div class="empty">Nog geen trainingen voor ${esc(team.name)}.</div>`;

  const squad=eventSquad(ev),c=eventAttendanceCounts(ev);
  return `<div class="toolbar"><div class="left"><select id="attendanceEvent" class="input">${events.map(e=>`<option value="${e.id}" ${e.id===ev.id?'selected':''}>${fmtDate(e.date)} · Training${e.focus?' · '+esc(e.focus):''}</option>`).join('')}</select></div><div class="right"><button class="btn ghost" data-edit-event-squad="${ev.id}">Groep aanpassen</button><button class="btn secondary" data-all-present>Iedereen aanwezig</button><button class="btn ghost" data-clear-attendance>Leegmaken</button></div></div>
  <section class="card"><div class="card-head"><div><p class="eyebrow">TRAINING</p><h2>${fmtLong(ev.date)}</h2><p class="muted small">${esc(team.name)} · groep ${squad.length} spelers · wedstrijden tellen hier niet mee</p></div>${ev.focus?`<span class="chip green">${esc(ev.focus)}</span>`:''}</div><div class="attendance-summary"><div class="summary-box"><span class="small muted">Aanwezig</span><strong class="success-text">${c.present}</strong></div><div class="summary-box"><span class="small muted">Afwezig</span><strong>${c.absent}</strong></div><div class="summary-box"><span class="small muted">Onbekend</span><strong>${c.unknown}</strong></div><div class="summary-box"><span class="small muted">Ingevuld</span><strong>${c.filled}/${c.total}</strong></div></div>
  <div class="table-wrap"><table><thead><tr><th>Speler</th><th>Positie</th><th>Status</th></tr></thead><tbody>${squad.map(p=>{const s=ev.attendance?.[p.id]||'';return `<tr class="${presentStatus(s)?'status-present':absentStatus(s)?'status-absent':''}"><td class="player-name">${esc(p.name)}</td><td>${esc(p.position||'–')}</td><td><select class="attendance-select" data-attendance-player="${p.id}">${attendanceOptions(s)}</select></td></tr>`}).join('')}</tbody></table></div></section>`;
}
function squadForm(ev){const teamId=ev.teamId||ui.teamId,teamPlayers=playersForTeam(teamId),availableElsewhere=availablePlayersForTeam(teamId).filter(p=>p.primaryTeamId!==teamId),selected=Array.isArray(ev.squadPlayerIds)&&ev.squadPlayerIds.length?ev.squadPlayerIds:teamPlayers.map(p=>p.id);return `<p class="muted small">Het team bestaat standaard alleen uit spelers waarvan dit het primaire team is. Spelers die alleen beschikbaar zijn voor dit team kun je hieronder handmatig aan deze training of wedstrijd toevoegen.</p><label class="check-item" style="margin-bottom:14px"><input id="squadUseWholeTeam" type="checkbox" ${!Array.isArray(ev.squadPlayerIds)||!ev.squadPlayerIds.length?'checked':''}> Hele primaire team gebruiken</label><h3 class="section-title">Eigen team</h3><div class="check-grid">${teamPlayers.map(p=>`<label class="check-item"><input type="checkbox" name="squadPlayer" value="${p.id}" ${selected.includes(p.id)?'checked':''}> ${esc(p.name)}</label>`).join('')}</div>${availableElsewhere.length?`<h3 class="section-title" style="margin-top:18px">Beschikbaar vanuit andere teams</h3><div class="check-grid">${availableElsewhere.map(p=>`<label class="check-item"><input type="checkbox" name="squadPlayer" value="${p.id}" ${selected.includes(p.id)?'checked':''}> ${esc(p.name)} <span class="muted tiny">· ${esc(teamName(p.primaryTeamId))}</span></label>`).join('')}</div>`:''}`}
function editEventSquad(id){const ev=eventById(id);if(!ev)return;modal('Groep voor deze activiteit',squadForm(ev),()=>{ev.squadPlayerIds=$('#squadUseWholeTeam').checked?null:$$('input[name=squadPlayer]:checked').map(x=>x.value);if(state.matches.some(m=>m.id===ev.id)){const allowed=new Set(eventPlayerIds(ev));ev.benchIds=(ev.benchIds||[]).filter(pid=>allowed.has(pid));Object.keys(ev.lineup||{}).forEach(slot=>{if(ev.lineup[slot]&&!allowed.has(ev.lineup[slot]))ev.lineup[slot]=null})}return true})}

function renderTrainings(){
  const team=activeTeam(),list=state.trainings.filter(t=>t.teamId===team.id).sort((a,b)=>b.date.localeCompare(a.date));
  if(!ui.trainingId||!trainingById(ui.trainingId)||trainingById(ui.trainingId).teamId!==team.id)ui.trainingId=(list.find(t=>t.date>=TODAY())||list[0])?.id||null;
  const t=trainingById(ui.trainingId);
  const listHtml=list.slice(0,80).map(x=>`<button class="event-card ${x.id===ui.trainingId?'active':''}" data-select-training="${x.id}"><strong>${fmtDate(x.date)}</strong><span class="muted small">${esc(x.focus||'Geen focus')} · ${(x.planItems||[]).reduce((a,p)=>a+number(p.duration),0)} min</span></button>`).join('');
  if(!t)return `<div class="toolbar"><div></div><button class="btn primary" data-add-training>＋ Training</button></div><div class="empty">Nog geen trainingen voor ${esc(team.name)}.</div>`;
  const duration=t.planItems.reduce((a,p)=>a+number(p.duration),0),squad=eventSquad(t),c=eventAttendanceCounts(t);
  return `<div class="toolbar"><div class="left"><button class="btn primary" data-add-training>＋ Training</button><button class="btn secondary" data-generate>✦ Trainingsgenerator</button></div><div class="right"><button class="btn ghost" data-edit-training="${t.id}">Bewerken</button><button class="btn ghost" data-edit-event-squad="${t.id}">Groep ${squad.length}</button></div></div>
  <div class="training-layout"><aside class="card"><div class="card-head"><div><p class="eyebrow">TRAININGEN</p><h2>${esc(team.name)}</h2></div></div><div class="event-list">${listHtml||'<div class="empty">Geen trainingen.</div>'}</div></aside>
  <div class="grid"><section class="card"><div class="card-head"><div><p class="eyebrow">TRAININGSPLAN</p><h2>${fmtLong(t.date)}</h2><p class="muted small">${esc(t.startTime||state.team.trainingTime||'20:00')} · ${esc(t.focus||'Geen focus')} · ${esc(t.intensity||'Middel')}</p></div><div style="text-align:right"><span class="muted small">Totale oefentijd</span><div class="duration-total">${duration} min</div></div></div>
  <div class="grid three" style="margin-bottom:16px"><div class="summary-box"><span class="small muted">Groep</span><strong>${squad.length}</strong></div><div class="summary-box"><span class="small muted">Aanwezig ingevuld</span><strong>${c.filled}/${c.total}</strong></div><div class="summary-box"><span class="small muted">Oefeningen</span><strong>${t.planItems.length}</strong></div></div>
  <div class="toolbar"><div class="left"><select id="planExerciseSelect" class="input"><option value="">Kies oefening...</option>${state.exercises.sort((a,b)=>a.name.localeCompare(b.name,'nl')).map(e=>`<option value="${e.id}">${esc(e.name)} · ${number(e.duration)} min</option>`).join('')}</select><button class="btn secondary" data-add-plan-item>＋ Aan plan</button></div><div class="right"><button class="btn ghost" data-attendance="${t.id}">Aanwezigheid</button></div></div>
  <div class="plan-stack">${t.planItems.length?t.planItems.map((pi,i)=>planItemHtml(t,pi,i)).join(''):'<div class="empty">Nog geen oefeningen. Voeg uit de bibliotheek toe of gebruik de generator.</div>'}</div>
  ${t.coachNotes?`<h3 class="section-title">Coachnotities training</h3><div class="callout">${nl2br(t.coachNotes)}</div>`:''}</section>
  ${ui.generatorPlan?renderGeneratorResult():renderGeneratorPanel()}</div></div>`
}
function planItemHtml(t,pi,i){const ex=exerciseById(pi.exerciseId);if(!ex)return '';return `<div class="plan-item"><div class="plan-order">${i+1}</div><div><div class="card-head" style="margin:0"><div><strong>${esc(ex.name)}</strong><div class="event-meta"><span class="chip">${esc(ex.category)}</span><span class="chip">${esc(ex.intensity)}</span>${ex.players?`<span class="chip">${esc(ex.players)} spelers</span>`:''}</div></div><strong>${number(pi.duration)} min</strong></div>${pi.coachPoints?.length?`<ul class="coach-points">${pi.coachPoints.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${pi.notes?`<div class="muted small" style="margin-top:8px">${nl2br(pi.notes)}</div>`:''}</div><div class="row-actions"><button class="btn ghost small-btn" data-plan-up="${pi.id}" ${i===0?'disabled':''}>↑</button><button class="btn ghost small-btn" data-plan-down="${pi.id}" ${i===t.planItems.length-1?'disabled':''}>↓</button><button class="btn ghost small-btn" data-edit-plan-item="${pi.id}">Coachpunten</button><button class="btn danger small-btn" data-remove-plan-item="${pi.id}">×</button></div></div>`}
function trainingForm(t={}){return `<div class="form-grid"><div class="field"><label>Datum</label><input id="fDate" class="input" type="date" value="${esc(t.date||TODAY())}"></div><div class="field"><label>Starttijd</label><input id="fTime" class="input" type="time" value="${esc(t.startTime||state.team.trainingTime||'20:00')}"></div><div class="field"><label>Team</label><select id="fTeam">${teamOptions(t.teamId||ui.teamId)}</select></div><div class="field"><label>Intensiteit</label><select id="fIntensity">${['Laag','Laag/middel','Middel','Middel/hoog','Hoog'].map(x=>`<option ${t.intensity===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Trainingsfocus</label><input id="fFocus" class="input" placeholder="Hoge pressing, opbouw, omschakeling..." value="${esc(t.focus||'')}"></div><div class="field full"><label>Coachnotities voor deze training</label><textarea id="fCoachNotes">${esc(t.coachNotes||'')}</textarea></div><div class="field full"><label>Overige notities</label><textarea id="fNotes">${esc(t.notes||'')}</textarea></div></div>`}
function editTraining(id){const t=id?trainingById(id):null;modal(t?'Training bewerken':'Training toevoegen',trainingForm(t||{}),()=>{const date=$('#fDate').value;if(!date){toast('Kies een datum');return false}const obj=t||{id:uid('tr'),attendance:{},planItems:[],exerciseIds:[],squadPlayerIds:null};Object.assign(obj,{date,startTime:$('#fTime').value,teamId:$('#fTeam').value,focus:$('#fFocus').value.trim(),intensity:$('#fIntensity').value,coachNotes:$('#fCoachNotes').value.trim(),notes:$('#fNotes').value.trim(),title:'Training'});if(!t)state.trainings.push(obj);state.trainings.sort((a,b)=>a.date.localeCompare(b.date));ui.teamId=obj.teamId;ui.trainingId=obj.id;return true})}
function addPlanItem(){const t=trainingById(ui.trainingId),eid=$('#planExerciseSelect')?.value;if(!t||!eid){toast('Kies eerst een oefening');return}const ex=exerciseById(eid);t.planItems.push({id:uid('pi'),exerciseId:eid,duration:number(ex.duration)||10,coachPoints:clone(ex.coachPoints||[]),notes:''});t.exerciseIds=t.planItems.map(x=>x.exerciseId);save()}
function editPlanItem(id){const t=trainingById(ui.trainingId),pi=t?.planItems.find(x=>x.id===id),ex=pi?exerciseById(pi.exerciseId):null;if(!pi||!ex)return;modal(`Coachpunten · ${ex.name}`,`<div class="form-grid"><div class="field"><label>Duur (min)</label><input id="fDuration" class="input" type="number" min="1" value="${number(pi.duration)}"></div><div class="field"><label>Bronoefening</label><input class="input" disabled value="${esc(ex.name)}"></div><div class="field full"><label>Coachpunten voor déze training (1 per regel)</label><textarea id="fCoachPoints">${esc((pi.coachPoints||[]).join('\n'))}</textarea><p class="muted tiny">Deze coachpunten mogen afwijken van de vaste coachpunten in de bibliotheek.</p></div><div class="field full"><label>Extra instructie / organisatie</label><textarea id="fPlanNotes">${esc(pi.notes||'')}</textarea></div></div>`,()=>{pi.duration=Math.max(1,number($('#fDuration').value));pi.coachPoints=$('#fCoachPoints').value.split('\n').map(x=>x.trim()).filter(Boolean);pi.notes=$('#fPlanNotes').value.trim();return true})}
function movePlanItem(id,dir){const t=trainingById(ui.trainingId),i=t?.planItems.findIndex(x=>x.id===id)??-1,j=i+dir;if(i<0||j<0||j>=t.planItems.length)return;[t.planItems[i],t.planItems[j]]=[t.planItems[j],t.planItems[i]];t.exerciseIds=t.planItems.map(x=>x.exerciseId);save()}
function removePlanItem(id){const t=trainingById(ui.trainingId);if(!t)return;t.planItems=t.planItems.filter(x=>x.id!==id);t.exerciseIds=t.planItems.map(x=>x.exerciseId);save()}
function renderGeneratorPanel(){const nm=nextMatch();return `<section class="card"><div class="card-head"><div><p class="eyebrow">SLIMME GENERATOR</p><h2>Training voorstellen</h2></div><span class="badge green">Lokaal</span></div><div class="form-grid"><div class="field"><label>Datum</label><input id="genDate" class="input" type="date" value="${esc(trainingById(ui.trainingId)?.date||TODAY())}"></div><div class="field"><label>Duur</label><input id="genDuration" class="input" type="number" min="30" max="150" value="90"></div><div class="field"><label>Spelers</label><input id="genPlayers" class="input" type="number" min="6" max="30" value="${eventSquad(trainingById(ui.trainingId)||{teamId:ui.teamId}).length||18}"></div><div class="field"><label>Focus</label><input id="genFocus" class="input" value="${esc(trainingById(ui.trainingId)?.focus||'Hoge pressing')}"></div></div>${nm?`<p class="muted small">Volgende wedstrijd: ${fmtDate(nm.date)} tegen ${esc(nm.opponent||'tegenstander')}. De generator houdt rekening met afstand tot de wedstrijd.</p>`:''}<button class="btn primary" data-run-generator>Maak voorstel</button></section>`}
function renderGeneratorResult(){const g=ui.generatorPlan;return `<section class="card"><div class="card-head"><div><p class="eyebrow">VOORSTEL</p><h2>${esc(g.focus)}</h2><p class="muted small">${fmtDate(g.date)} · ${g.players} spelers · ${g.total} min</p></div><button class="btn ghost small-btn" data-clear-generator>×</button></div><div class="plan-stack">${g.items.map((it,i)=>{const ex=exerciseById(it.exerciseId);return `<div class="plan-item"><div class="plan-order">${i+1}</div><div><strong>${esc(ex?.name||'Oefening')}</strong><div class="muted small">${it.duration} min · ${esc(ex?.category||'')}</div><ul class="coach-points">${(it.coachPoints||[]).slice(0,4).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div>`}).join('')}</div><div class="callout" style="margin-top:12px">${esc(g.advice)}</div><div style="margin-top:14px;display:flex;gap:8px"><button class="btn primary" data-save-generator>In training zetten</button><button class="btn ghost" data-clear-generator>Annuleren</button></div></section>`}
function daysBetween(a,b){return Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)}
function generateTrainingPlan(){const date=$('#genDate')?.value||TODAY(),target=Math.max(30,number($('#genDuration')?.value)||90),players=Math.max(6,number($('#genPlayers')?.value)||18),focus=($('#genFocus')?.value||'Voetbal').trim();const q=focus.toLowerCase(),nm=state.matches.filter(m=>m.teamId===ui.teamId&&m.date>=date).sort((a,b)=>a.date.localeCompare(b.date))[0];const toMatch=nm?daysBetween(date,nm.date):99;let wanted=[];
  if(/press|druk|verded|compact/.test(q))wanted=['pressing','compact','omschakeling','teamtactiek'];else if(/opbouw|balbezit|positiespel/.test(q))wanted=['opbouw','balbezit','passing','positie'];else if(/afwerk|scor|aanval/.test(q))wanted=['afwerken','combinatie','wedstrijdgericht'];else wanted=q.split(/\s+/).filter(x=>x.length>3);
  const eligible=state.exercises.filter(e=>{const p=String(e.players||'');const nums=(p.match(/\d+/g)||[]).map(Number);if(!nums.length)return true;const min=Math.min(...nums),max=Math.max(...nums);return players>=min-2&&players<=max+6});
  const score=e=>{const text=[e.name,e.category,e.description,...(e.tags||[])].join(' ').toLowerCase();let s=wanted.reduce((a,w)=>a+(text.includes(w)?4:0),0);if(e.category==='Warming-up')s+=1;if(toMatch<=2&&/Hoog/i.test(e.intensity))s-=3;if(toMatch>=3&&toMatch<=5&&/Hoog/i.test(e.intensity))s+=1;return s+Math.random()*.8};
  const warm=eligible.filter(e=>/warming/i.test(e.category)).sort((a,b)=>score(b)-score(a))[0]||eligible[0];const rest=eligible.filter(e=>e.id!==warm?.id).sort((a,b)=>score(b)-score(a));const chosen=[warm,...rest.slice(0,4)].filter(Boolean);let remaining=target,items=[];chosen.forEach((e,i)=>{let dur=i===0?Math.min(12,number(e.duration)||10):number(e.duration)||15;if(i===chosen.length-1)dur=Math.max(10,remaining);if(dur>remaining&&remaining>=8)dur=remaining;if(remaining>0){items.push({exerciseId:e.id,duration:dur,coachPoints:clone(e.coachPoints||[])});remaining-=dur}});if(remaining>4&&items.length)items[items.length-1].duration+=remaining;const advice=toMatch<=2?'Wedstrijd dichtbij: houd de intensieve blokken kort en leg meer nadruk op tactische helderheid, snelheid en wedstrijdvoorbereiding.':toMatch<=5?'Geschikt moment voor een stevige voetbalconditionele prikkel, gevolgd door teamtactiek.':'Geen wedstrijd op korte termijn gevonden; belasting kan vooral vanuit trainingsdoel en spelersbeschikbaarheid worden gekozen.';ui.generatorPlan={date,focus,players,total:target,items,advice};renderPage()}
function saveGenerator(){const g=ui.generatorPlan;if(!g)return;let t=state.trainings.find(x=>x.teamId===ui.teamId&&x.date===g.date);if(!t){t={id:uid('tr'),date:g.date,title:'Training',startTime:state.team.trainingTime||'20:00',teamId:ui.teamId,attendance:{},squadPlayerIds:null,notes:'',coachNotes:'',focus:g.focus,intensity:'Middel',planItems:[],exerciseIds:[]};state.trainings.push(t)}t.focus=g.focus;t.planItems=g.items.map(it=>({id:uid('pi'),exerciseId:it.exerciseId,duration:it.duration,coachPoints:clone(it.coachPoints),notes:''}));t.exerciseIds=t.planItems.map(x=>x.exerciseId);ui.trainingId=t.id;ui.generatorPlan=null;save();toast('Trainingsvoorstel opgeslagen')}

function renderExercises(){const q=ui.exerciseSearch.toLowerCase(),cats=[...new Set(state.exercises.map(e=>e.category))].sort();const list=state.exercises.filter(e=>(!q||[e.name,e.category,e.description,e.goal,e.organization,(e.tags||[]).join(' '),(e.coachPoints||[]).join(' ')].join(' ').toLowerCase().includes(q))&&(!ui.exerciseCategory||e.category===ui.exerciseCategory));return `<div class="toolbar"><div class="left"><input id="exerciseSearch" class="input" placeholder="Zoek op oefening, coachpunt, doel..." value="${esc(ui.exerciseSearch)}"><select id="exerciseCategory"><option value="">Alle categorieën</option>${cats.map(c=>`<option ${c===ui.exerciseCategory?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="right"><button class="btn secondary" data-go="documents">⌁ Uit document halen</button><button class="btn primary" data-add-exercise>＋ Oefening</button></div></div><div class="exercise-grid">${list.map(exerciseCard).join('')||'<div class="empty">Geen oefeningen gevonden.</div>'}</div>`}
function exerciseCard(e){const doc=e.sourceDocId?state.documents.find(d=>d.id===e.sourceDocId):null;return `<article class="card exercise-card"><div class="card-head"><div><p class="eyebrow">${esc(e.category)}</p><h2>${esc(e.name)}</h2></div><span class="badge ${/hoog/i.test(e.intensity)?'orange':'green'}">${esc(e.intensity)}</span></div><div class="chips"><span class="chip">${number(e.duration)} min</span>${e.players?`<span class="chip">${esc(e.players)} spelers</span>`:''}${e.size?`<span class="chip">${esc(e.size)}</span>`:''}</div><p>${esc(e.description||e.goal||'Geen beschrijving.')}</p>${e.coachPoints?.length?`<strong class="small">Coachpunten</strong><ul class="coach-points">${e.coachPoints.slice(0,4).map(x=>`<li>${esc(x)}</li>`).join('')}${e.coachPoints.length>4?`<li>+ ${e.coachPoints.length-4} meer</li>`:''}</ul>`:''}<div class="footer"><div>${doc?`<span class="source-tag">Bron: ${esc(doc.name)}</span>`:''}</div><div class="row-actions"><button class="btn ghost small-btn" data-edit-exercise="${e.id}">Bewerk</button><button class="btn ghost small-btn" data-delete-exercise="${e.id}">×</button></div></div></article>`}
function exerciseForm(e={}){return `<div class="form-grid"><div class="field full"><label>Naam</label><input id="fExName" class="input" value="${esc(e.name||'')}"></div><div class="field"><label>Categorie</label><input id="fExCat" class="input" value="${esc(e.category||'')}"></div><div class="field"><label>Intensiteit</label><input id="fExIntensity" class="input" value="${esc(e.intensity||'Middel')}"></div><div class="field"><label>Spelers</label><input id="fExPlayers" class="input" placeholder="12-18" value="${esc(e.players||'')}"></div><div class="field"><label>Duur (min)</label><input id="fExDuration" class="input" type="number" min="1" value="${number(e.duration)||10}"></div><div class="field"><label>Afmeting</label><input id="fExSize" class="input" placeholder="30 x 25 m" value="${esc(e.size||'')}"></div><div class="field"><label>Materiaal</label><input id="fExMaterials" class="input" value="${esc(e.materials||'')}"></div><div class="field full"><label>Doel</label><textarea id="fExGoal">${esc(e.goal||'')}</textarea></div><div class="field full"><label>Organisatie / uitvoering</label><textarea id="fExOrg">${esc(e.organization||e.description||'')}</textarea></div><div class="field full"><label>Coachpunten (1 per regel)</label><textarea id="fExCoach">${esc((e.coachPoints||[]).join('\n'))}</textarea></div><div class="field full"><label>Variaties / progressies</label><textarea id="fExVar">${esc(e.variations||'')}</textarea></div><div class="field full"><label>Tags (komma gescheiden)</label><input id="fExTags" class="input" value="${esc((e.tags||[]).join(', '))}"></div></div>`}
function editExercise(id){const e=id?exerciseById(id):null;modal(e?'Oefening bewerken':'Oefening toevoegen',exerciseForm(e||{}),()=>{const name=$('#fExName').value.trim();if(!name){toast('Vul een naam in');return false}const obj=e||{id:uid('ex'),sourceDocId:null};Object.assign(obj,{name,category:$('#fExCat').value.trim()||'Overig',intensity:$('#fExIntensity').value.trim()||'Middel',players:$('#fExPlayers').value.trim(),duration:Math.max(1,number($('#fExDuration').value)||10),size:$('#fExSize').value.trim(),materials:$('#fExMaterials').value.trim(),goal:$('#fExGoal').value.trim(),organization:$('#fExOrg').value.trim(),description:$('#fExOrg').value.trim(),coachPoints:$('#fExCoach').value.split('\n').map(x=>x.trim()).filter(Boolean),variations:$('#fExVar').value.trim(),tags:$('#fExTags').value.split(',').map(x=>x.trim()).filter(Boolean)});if(!e)state.exercises.push(obj);return true})}

function renderDocuments(){return `<div class="grid two"><section class="card"><div class="card-head"><div><p class="eyebrow">DOCUMENTIMPORT</p><h2>Oefeningen uit bronnen halen</h2></div><span class="badge green">Lokaal lezen</span></div><div class="document-drop"><h2>PDF, Word, Excel of tekst</h2><p class="muted small">De browser leest het bestand op jouw apparaat. De tekst wordt lokaal onderzocht op oefeningsblokken, coachpunten, duur, spelers en organisatie.</p><button class="btn primary" data-pick-document>Kies document</button><p class="tiny muted">Ondersteund: PDF, DOCX, XLSX/XLSM/XLS, TXT, MD, CSV. Oud .DOC-formaat eerst opslaan als .docx.</p></div>${ui.docFilename?`<div class="callout" style="margin-top:14px">Gelezen: <strong>${esc(ui.docFilename)}</strong> · ${ui.docCandidates.length} mogelijke oefeningen gevonden.</div>`:''}</section><section class="card"><div class="card-head"><div><p class="eyebrow">BRONNEN</p><h2>Geïmporteerde documenten</h2></div></div>${state.documents.length?state.documents.slice().sort((a,b)=>(b.importedAt||'').localeCompare(a.importedAt||'')).map(d=>`<div class="list-row"><div><strong>${esc(d.name)}</strong><div class="muted tiny">${fmtDate((d.importedAt||'').slice(0,10))} · ${d.exerciseCount||0} oefeningen toegevoegd</div></div><button class="btn ghost small-btn" data-delete-document="${d.id}">Verwijder bronverwijzing</button></div>`).join(''):'<div class="empty">Nog geen documenten geïmporteerd.</div>'}</section></div>${ui.docCandidates.length?renderDocumentCandidates():''}`}
function renderDocumentCandidates(){return `<section class="card" style="margin-top:16px"><div class="card-head"><div><p class="eyebrow">CONTROLEER</p><h2>${ui.docCandidates.length} gevonden oefeningen</h2><p class="muted small">Controleer de kandidaten. Na import kun je iedere oefening verder bewerken in de bibliotheek.</p></div><div class="row-actions"><button class="btn ghost small-btn" data-doc-select-all>Alles selecteren</button><button class="btn primary" data-import-doc-candidates>Geselecteerde toevoegen</button></div></div><div class="candidate-grid">${ui.docCandidates.map((c,i)=>`<div class="candidate-card ${c.selected?'selected':''}"><label class="check-item"><input type="checkbox" data-doc-candidate="${i}" ${c.selected?'checked':''}> <strong>${esc(c.name)}</strong></label><div class="chips" style="margin-top:8px"><span class="chip">${esc(c.category||'Uit document')}</span><span class="chip">${number(c.duration)||10} min</span>${c.players?`<span class="chip">${esc(c.players)}</span>`:''}</div><p class="small">${esc((c.organization||c.description||'').slice(0,240))}${(c.organization||c.description||'').length>240?'…':''}</p>${c.coachPoints?.length?`<ul class="coach-points">${c.coachPoints.slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<button class="btn ghost small-btn" data-edit-doc-candidate="${i}">Kandidaat bewerken</button></div>`).join('')}</div></section>`}
async function readDocumentFile(file){const ext=file.name.toLowerCase().split('.').pop();if(['txt','md','csv'].includes(ext))return await file.text();if(ext==='docx'){if(!window.mammoth)throw new Error('Word-lezer kon niet laden. Controleer internetverbinding en probeer opnieuw.');const r=await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return r.value||''}if(['xlsx','xlsm','xls'].includes(ext)){if(!window.XLSX)throw new Error('Excel-lezer kon niet laden.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});return wb.SheetNames.map(n=>`\n# Werkblad: ${n}\n`+XLSX.utils.sheet_to_csv(wb.Sheets[n])).join('\n')}if(ext==='pdf'){const lib=window.pdfjsLib;if(!lib)throw new Error('PDF-lezer kon niet laden.');lib.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';const pdf=await lib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;let text='';for(let i=1;i<=pdf.numPages;i++){const pg=await pdf.getPage(i),tc=await pg.getTextContent();text+=`\n# Pagina ${i}\n`+tc.items.map(x=>x.str).join(' ')+'\n'}return text}if(ext==='doc')throw new Error('Oud .doc-formaat wordt niet veilig in de browser gelezen. Sla het bestand op als .docx.');throw new Error('Bestandstype niet ondersteund')}
function lineValue(block,label){const re=new RegExp(`(?:^|\\n)\\s*(?:${label})\\s*[:\\-]\\s*([^\\n]+)`,'i'),m=block.match(re);return m?m[1].trim():''}
function multilineValue(block,label){const labels='(?:doel|goal|organisatie|organization|uitvoering|omschrijving|beschrijving|description|coach(?:ing|punten)?|aandachtspunten|duur|duration|spelers|players|afmeting|veld|size|materiaal|materials|variaties?|progressie|tags|categorie|category)';const re=new RegExp(`(?:^|\\n)\\s*(?:${label})\\s*[:\\-]\\s*([\\s\\S]*?)(?=\\n\\s*${labels}\\s*[:\\-]|$)`,'i'),m=block.match(re);return m?m[1].trim():''}
function guessCategory(text){const x=text.toLowerCase();if(/rondo|warming|warm.?up/.test(x))return 'Warming-up';if(/afwerk|schot|finish/.test(x))return 'Techniek';if(/1\s*(tegen|v)\s*1|duel/.test(x))return 'Duelkracht';if(/positiespel|balbezit/.test(x))return 'Positiespel';if(/press|compact|opbouw|tact/.test(x))return 'Tactiek';if(/wedstrijd|partij|ssg|[3-9]\s*v\s*[3-9]/.test(x))return 'SSG';if(/condition|interval|herhaal/.test(x))return 'Conditioneel';return 'Uit document'}
function extractExercisesFromText(text){const cleaned=String(text||'').replace(/\r/g,'').replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n');let blocks=cleaned.split(/\n\s*\n/).map(x=>x.trim()).filter(x=>x.length>=40);if(blocks.length<3){blocks=cleaned.split(/(?=\n\s*(?:oefening|exercise|vorm)\s*\d*\s*[:\-])/i).map(x=>x.trim()).filter(x=>x.length>=40)}const football=/bal|speler|doel|keeper|vak|veld|tegen|rondo|press|pass|afwerk|positiespel|voetbal|omschakel|dribbel|wedstrijd|coaching|coachpunt|organisatie|1v1|2v2|3v3|4v4|5v5|6v6|7v7|8v8|9v9|10v10|11v11/i;const seen=new Set(),out=[];for(const block of blocks){if(!football.test(block))continue;const lines=block.split('\n').map(x=>x.trim()).filter(Boolean);let name=lineValue(block,'oefening|exercise|naam|name|titel|title')||lines.find(x=>x.length>=4&&x.length<=90&&!/^(doel|organisatie|coach|duur|spelers|afmeting|materiaal)\b/i.test(x))||'';name=name.replace(/^\d+[.)]\s*/,'').replace(/^(oefening|exercise|vorm)\s*\d*\s*[:\-]?\s*/i,'').trim();if(name.length<3||name.length>110)continue;const key=name.toLowerCase();if(seen.has(key))continue;const goal=multilineValue(block,'doel|goal'),org=multilineValue(block,'organisatie|organization|uitvoering|omschrijving|beschrijving|description'),coachRaw=multilineValue(block,'coach(?:ing|punten)?|aandachtspunten'),players=lineValue(block,'spelers|players|aantal spelers'),size=lineValue(block,'afmeting|veld|size'),materials=lineValue(block,'materiaal|materials'),durRaw=lineValue(block,'duur|duration|tijd'),dur=(durRaw.match(/\d+/)||[])[0];let coachPoints=coachRaw.split(/\n|[•·]|\s+-\s+/).map(x=>x.replace(/^[-–—*]\s*/,'').trim()).filter(x=>x.length>3&&x.length<180);if(!coachPoints.length){coachPoints=lines.filter(x=>/coach|let op|aandacht|accent/i.test(x)).map(x=>x.replace(/^[^:]*:\s*/,'')).filter(Boolean).slice(0,6)}const desc=(org||goal||block).replace(/\s+/g,' ').slice(0,1200);out.push({name,category:guessCategory(block),duration:dur?Number(dur):10,players,size,materials,goal,organization:org||desc,description:desc,intensity:/hoog|intensief/i.test(block)?'Hoog':/laag/i.test(block)?'Laag':'Middel',coachPoints,tags:[],variations:multilineValue(block,'variaties?|progressie'),selected:true});seen.add(key);if(out.length>=80)break}return out}
async function handleDocument(file){try{toast('Document wordt lokaal gelezen…');const text=await readDocumentFile(file);if(!text.trim())throw new Error('Geen leesbare tekst gevonden');const c=extractExercisesFromText(text);ui.docFilename=file.name;ui.docText=text;ui.docCandidates=c;renderPage();toast(`${c.length} mogelijke oefeningen gevonden`)}catch(e){toast('Document lezen mislukt: '+e.message)}}
function editDocCandidate(i){const c=ui.docCandidates[i];if(!c)return;modal('Gevonden oefening bewerken',exerciseForm(c),()=>{Object.assign(c,{name:$('#fExName').value.trim(),category:$('#fExCat').value.trim()||'Uit document',intensity:$('#fExIntensity').value.trim()||'Middel',players:$('#fExPlayers').value.trim(),duration:Math.max(1,number($('#fExDuration').value)||10),size:$('#fExSize').value.trim(),materials:$('#fExMaterials').value.trim(),goal:$('#fExGoal').value.trim(),organization:$('#fExOrg').value.trim(),description:$('#fExOrg').value.trim(),coachPoints:$('#fExCoach').value.split('\n').map(x=>x.trim()).filter(Boolean),variations:$('#fExVar').value.trim(),tags:$('#fExTags').value.split(',').map(x=>x.trim()).filter(Boolean)});return true},{afterSave:()=>renderPage()})}
function importDocCandidates(){const selected=ui.docCandidates.filter(c=>c.selected&&c.name);if(!selected.length){toast('Selecteer minimaal één oefening');return}const doc={id:uid('doc'),name:ui.docFilename,importedAt:new Date().toISOString(),exerciseCount:selected.length,characterCount:ui.docText.length};state.documents.push(doc);selected.forEach(c=>state.exercises.push({...clone(c),id:uid('ex'),sourceDocId:doc.id}));ui.docCandidates=[];ui.docFilename='';ui.docText='';save();toast(`${selected.length} oefeningen toegevoegd aan bibliotheek`)}

function renderMatches(){
  const team=activeTeam(),list=state.matches.filter(m=>m.teamId===team.id).sort((a,b)=>b.date.localeCompare(a.date));if(!ui.matchId||!matchById(ui.matchId)||matchById(ui.matchId).teamId!==team.id)ui.matchId=(list.find(m=>m.date>=TODAY())||list[0])?.id||null;const m=matchById(ui.matchId);if(!m)return `<div class="toolbar"><div></div><button class="btn primary" data-add-match>＋ Wedstrijd</button></div><div class="empty">Nog geen wedstrijden voor ${esc(team.name)}.</div>`;
  const squad=eventSquad(m),used=new Set(Object.values(m.lineup||{}).filter(Boolean)),score=(m.goalsFor!==''||m.goalsAgainst!=='')?`${m.goalsFor||0} - ${m.goalsAgainst||0}`:'vs';
  return `<div class="toolbar match-toolbar"><div class="left"><select id="matchSelect" class="input">${list.map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${fmtDate(x.date)} · ${esc(x.opponent||'Wedstrijd')}</option>`).join('')}</select><button class="btn primary" data-add-match>＋ Wedstrijd</button></div><div class="right"><button class="btn ghost" data-edit-match="${m.id}">Wedstrijdplan</button><button class="btn ghost" data-edit-event-squad="${m.id}">Selectie ${squad.length}</button></div></div>
  <div class="grid two match-page-grid"><section class="card match-main-card"><div class="card-head"><div><p class="eyebrow">${esc(m.competition||'WEDSTRIJD')}</p><h2>${esc(team.name)} · ${esc(m.opponent||'Tegenstander')}</h2><p class="muted small">${fmtLong(m.date)} · ${esc(m.homeAway||'')} ${m.venue?'· '+esc(m.venue):''}</p></div><select id="matchFormation" class="formation-select">${formationOptions(m.formation)}</select></div><div class="match-score"><input id="matchGoalsFor" class="input score-input" inputmode="numeric" value="${esc(m.goalsFor)}"><strong>${score==='vs'?'–':'-'}</strong><input id="matchGoalsAgainst" class="input score-input" inputmode="numeric" value="${esc(m.goalsAgainst)}"><button class="btn ghost small-btn" data-save-score>Score opslaan</button></div>${renderLineupBoard(m)}</section>
  <div class="grid"><section class="card"><div class="card-head"><div><p class="eyebrow">VOORBEREIDING</p><h2>Wedstrijdchecklist</h2></div></div><div class="checklist">${Object.entries(CHECKLIST_LABELS).map(([k,l])=>`<label class="check-row"><input type="checkbox" data-match-check="${k}" ${m.checklist[k]?'checked':''}> ${l}</label>`).join('')}</div></section><section class="card"><div class="card-head"><div><p class="eyebrow">WEDSTRIJDPLAN</p><h2>Afspraken</h2></div><button class="btn ghost small-btn" data-edit-match="${m.id}">Bewerk</button></div>${['teamGoal','pressing','buildUp','setPieces','individual'].map(k=>{const labels={teamGoal:'Teamdoel',pressing:'Pressing',buildUp:'Opbouw',setPieces:'Standaardsituaties',individual:'Individuele opdrachten'};return `<div class="list-row"><div><strong>${labels[k]}</strong><div class="muted small">${esc(m.plan[k]||'Nog niet ingevuld')}</div></div></div>`}).join('')}</section><section class="card"><div class="card-head"><div><p class="eyebrow">SPELERS</p><h2>Wedstrijdstatistieken</h2></div></div><div class="table-wrap"><table><thead><tr><th>Speler</th><th>Min</th><th>G</th><th>A</th><th></th></tr></thead><tbody>${squad.map(p=>{const s=m.playerStats[p.id]||{};return `<tr><td>${esc(p.name)}</td><td>${number(s.minutes)}</td><td>${number(s.goals)}</td><td>${number(s.assists)}</td><td><button class="btn ghost small-btn" data-edit-match-stat="${p.id}">Bewerk</button></td></tr>`}).join('')}</tbody></table></div></section></div></div>
  <section class="card" style="margin-top:16px"><div class="card-head"><div><p class="eyebrow">NA DE WEDSTRIJD</p><h2>Evaluatie → volgende training</h2></div><button class="btn ghost" data-edit-match="${m.id}">Evaluatie bewerken</button></div><div class="grid three"><div class="callout"><strong>Goed</strong><p class="small">${nl2br(m.evaluation.good||'Nog niet ingevuld')}</p></div><div class="callout orange"><strong>Verbeteren</strong><p class="small">${nl2br(m.evaluation.improve||'Nog niet ingevuld')}</p></div><div class="callout"><strong>Volgende training</strong><p class="small">${nl2br(m.evaluation.nextTraining||'Nog niet ingevuld')}</p>${m.evaluation.nextTraining?`<button class="btn secondary small-btn" data-training-from-match="${m.id}">Maak trainingsfocus</button>`:''}</div></div></section>`
}
function renderLineupBoard(m){const slots=FORMATIONS[m.formation]||FORMATIONS['4-3-3'],starters=new Set(Object.values(m.lineup||{}).filter(Boolean)),benchPlayers=(m.benchIds||[]).map(playerById).filter(p=>p&&eventPlayerIds(m).includes(p.id)&&!starters.has(p.id));return `<div class="pitch-wrap"><div class="pitch" data-lineup-pitch="${m.id}"><div class="pitch-box top"></div><div class="pitch-box bottom"></div>${slots.map(([id,label,x,y])=>{const pid=m.lineup?.[id],p=playerById(pid);return `<button class="pitch-slot ${p?'filled':''}" style="left:${x}%;top:${y}%" data-lineup-slot="${id}" data-match-id="${m.id}"><span>${p?`${esc(p.number?`#${p.number} `:'')}${esc(p.name.split(' ')[0])}`:esc(label)}</span></button>`}).join('')}</div><div class="bench-panel"><div class="bank-head"><div><strong>Bank</strong><p class="muted tiny">Alleen de wisselspelers die jij hebt gekozen.</p></div><button class="btn ghost small-btn" data-edit-bench>Bank kiezen</button></div><div class="squad-list bank-list">${benchPlayers.map(p=>`<button class="player-chip bench-selected" data-toggle-bench="${p.id}">${esc(p.number?`#${p.number} `:'')}${esc(p.name)} <span class="selection-state">Bank</span></button>`).join('')||'<span class="muted small">Nog geen wisselspelers gekozen.</span>'}</div><div class="divider"></div><button class="btn ghost small-btn" data-clear-lineup>Opstelling leegmaken</button></div></div>`}

function editBenchSelection(){const m=matchById(ui.matchId);if(!m)return;const starters=new Set(Object.values(m.lineup||{}).filter(Boolean)),available=eventSquad(m).filter(p=>!starters.has(p.id)),selected=new Set((m.benchIds||[]).filter(id=>available.some(p=>p.id===id)));modal('Bank kiezen',`<p class="muted small">Kies alleen de spelers die als wissel op de bank zitten. Spelers in de basis staan hier niet tussen.</p><div class="check-grid bench-picker">${available.map(p=>`<label class="check-item"><input type="checkbox" name="benchPlayer" value="${p.id}" ${selected.has(p.id)?'checked':''}> <span><strong>${esc(p.name)}</strong>${p.position?`<small class="muted">${esc(p.position)}</small>`:''}</span></label>`).join('')||'<div class="empty">Geen spelers beschikbaar buiten de basis.</div>'}</div>`,()=>{m.benchIds=$$('input[name=benchPlayer]:checked').map(x=>x.value);return true},{saveText:'Bank opslaan'})}
function matchForm(m={}){const plan=m.plan||{},ev=m.evaluation||{};return `<div class="form-grid"><div class="field"><label>Datum</label><input id="fMatchDate" class="input" type="date" value="${esc(m.date||TODAY())}"></div><div class="field"><label>Tijd</label><input id="fMatchTime" class="input" type="time" value="${esc(m.startTime||'')}"></div><div class="field"><label>Team</label><select id="fMatchTeam">${teamOptions(m.teamId||ui.teamId)}</select></div><div class="field"><label>Thuis/uit</label><select id="fMatchHome"><option ${m.homeAway==='Thuis'?'selected':''}>Thuis</option><option ${m.homeAway==='Uit'?'selected':''}>Uit</option></select></div><div class="field full"><label>Tegenstander</label><input id="fOpponent" class="input" value="${esc(m.opponent||'')}"></div><div class="field"><label>Competitie</label><input id="fCompetition" class="input" placeholder="Competitie / beker / oefen" value="${esc(m.competition||'')}"></div><div class="field"><label>Locatie</label><input id="fVenue" class="input" value="${esc(m.venue||'')}"></div><div class="field"><label>Formatie</label><select id="fMatchFormation">${formationOptions(m.formation||activeTeam()?.formation||'4-3-3')}</select></div><div class="field full"><label>Teamdoel</label><textarea id="fPlanGoal">${esc(plan.teamGoal||'')}</textarea></div><div class="field full"><label>Pressingafspraken</label><textarea id="fPlanPress">${esc(plan.pressing||'')}</textarea></div><div class="field full"><label>Opbouwafspraken</label><textarea id="fPlanBuild">${esc(plan.buildUp||'')}</textarea></div><div class="field full"><label>Standaardsituaties</label><textarea id="fPlanSet">${esc(plan.setPieces||'')}</textarea></div><div class="field full"><label>Individuele opdrachten</label><textarea id="fPlanInd">${esc(plan.individual||'')}</textarea></div><div class="field full"><label>Algemene notities</label><textarea id="fMatchNotes">${esc(m.notes||'')}</textarea></div><div class="field full"><h3>Evaluatie</h3></div><div class="field full"><label>Wat ging goed?</label><textarea id="fEvalGood">${esc(ev.good||'')}</textarea></div><div class="field full"><label>Wat moet beter?</label><textarea id="fEvalImprove">${esc(ev.improve||'')}</textarea></div><div class="field full"><label>Wat moet terugkomen in de volgende training?</label><textarea id="fEvalNext">${esc(ev.nextTraining||'')}</textarea></div></div>`}
function editMatch(id){const m=id?matchById(id):null;modal(m?'Wedstrijd bewerken':'Wedstrijd toevoegen',matchForm(m||{}),()=>{const date=$('#fMatchDate').value;if(!date){toast('Kies een datum');return false}const obj=m||{id:uid('m'),attendance:{},lineup:{},squadPlayerIds:null,playerStats:{},checklist:{selection:false,lineup:false,opponent:false,setPieces:false,warmup:false,materials:false}};Object.assign(obj,{date,startTime:$('#fMatchTime').value,teamId:$('#fMatchTeam').value,homeAway:$('#fMatchHome').value,opponent:$('#fOpponent').value.trim(),competition:$('#fCompetition').value.trim(),venue:$('#fVenue').value.trim(),formation:$('#fMatchFormation').value,notes:$('#fMatchNotes').value.trim(),plan:{teamGoal:$('#fPlanGoal').value.trim(),pressing:$('#fPlanPress').value.trim(),buildUp:$('#fPlanBuild').value.trim(),setPieces:$('#fPlanSet').value.trim(),individual:$('#fPlanInd').value.trim()},evaluation:{good:$('#fEvalGood').value.trim(),improve:$('#fEvalImprove').value.trim(),nextTraining:$('#fEvalNext').value.trim()}});if(!m)state.matches.push(obj);state.matches.sort((a,b)=>a.date.localeCompare(b.date));ui.teamId=obj.teamId;ui.matchId=obj.id;return true})}
function assignLineup(matchId,slotId,playerId){const m=matchById(matchId);if(!m)return;Object.keys(m.lineup).forEach(k=>{if(m.lineup[k]===playerId)m.lineup[k]=null});m.lineup[slotId]=playerId;m.benchIds=(m.benchIds||[]).filter(id=>id!==playerId);m.formation=m.formation||'4-3-3';m.checklist.lineup=Object.values(m.lineup).filter(Boolean).length>=11;save()}
function toggleBenchPlayer(playerId){const m=matchById(ui.matchId);if(!m)return;const starters=new Set(Object.values(m.lineup||{}).filter(Boolean));if(starters.has(playerId)){toast('Deze speler staat in de basis. Haal hem eerst uit de opstelling.');return}if(!eventPlayerIds(m).includes(playerId)){toast('Deze speler zit niet in de wedstrijdselectie.');return}m.benchIds??=[];m.benchIds=m.benchIds.includes(playerId)?m.benchIds.filter(id=>id!==playerId):[...m.benchIds,playerId];save()}
function chooseLineupPlayer(matchId,slotId){const m=matchById(matchId);if(!m)return;const current=m.lineup?.[slotId]||'';modal('Speler op positie',`<div class="field"><label>Speler</label><select id="fSlotPlayer" class="input"><option value="">Leeg</option>${eventSquad(m).map(p=>`<option value="${p.id}" ${p.id===current?'selected':''}>${esc(p.name)} ${p.position?'· '+esc(p.position):''}</option>`).join('')}</select></div>`,()=>{const pid=$('#fSlotPlayer').value;if(pid)assignLineup(matchId,slotId,pid);else{m.lineup[slotId]=null;save({render:false});}return true})}
function editMatchStat(playerId){const m=matchById(ui.matchId),p=playerById(playerId),s=m?.playerStats?.[playerId]||{};if(!m||!p)return;modal(`Wedstrijdstatistiek · ${p.name}`,`<div class="form-grid"><div class="field"><label>Basis</label><select id="fStarted"><option value="0" ${!s.started?'selected':''}>Nee</option><option value="1" ${s.started?'selected':''}>Ja</option></select></div><div class="field"><label>Minuten</label><input id="fMinutes" class="input" type="number" min="0" max="130" value="${number(s.minutes)}"></div><div class="field"><label>Goals</label><input id="fGoals" class="input" type="number" min="0" value="${number(s.goals)}"></div><div class="field"><label>Assists</label><input id="fAssists" class="input" type="number" min="0" value="${number(s.assists)}"></div><div class="field"><label>Geel</label><input id="fYellow" class="input" type="number" min="0" value="${number(s.yellow)}"></div><div class="field"><label>Rood</label><input id="fRed" class="input" type="number" min="0" value="${number(s.red)}"></div></div>`,()=>{m.playerStats[playerId]={started:$('#fStarted').value==='1',minutes:number($('#fMinutes').value),goals:number($('#fGoals').value),assists:number($('#fAssists').value),yellow:number($('#fYellow').value),red:number($('#fRed').value)};return true})}
function trainingFromMatch(matchId){const m=matchById(matchId);if(!m||!m.evaluation.nextTraining)return;const future=state.trainings.filter(t=>t.teamId===m.teamId&&t.date>m.date).sort((a,b)=>a.date.localeCompare(b.date))[0];if(future){future.focus=m.evaluation.nextTraining;ui.trainingId=future.id;setPage('trainings');save({render:false});toast('Trainingsfocus gekoppeld aan eerstvolgende training')}else{const d=new Date(m.date+'T12:00:00');d.setDate(d.getDate()+3);const date=d.toLocaleDateString('sv-SE');const t={id:uid('tr'),date,title:'Training',startTime:state.team.trainingTime||'20:00',teamId:m.teamId,attendance:{},squadPlayerIds:null,notes:'',coachNotes:'',focus:m.evaluation.nextTraining,intensity:'Middel',planItems:[],exerciseIds:[]};state.trainings.push(t);ui.trainingId=t.id;save({render:false});setPage('trainings');toast('Nieuwe training gemaakt vanuit wedstrijdevaluatie')}}

function renderTactics(){const team=activeTeam(),list=state.tactics.filter(t=>t.teamId===team.id);if(!ui.tacticId||!tacticById(ui.tacticId)||tacticById(ui.tacticId).teamId!==team.id)ui.tacticId=list[0]?.id||null;const t=tacticById(ui.tacticId);return `<div class="toolbar"><div class="left"><button class="btn primary" data-add-tactic>＋ Tactiek</button></div><div class="right">${t?`<button class="btn ghost" data-edit-tactic="${t.id}">Afspraken bewerken</button>`:''}</div></div>${t?`<div class="tactic-layout"><aside class="card"><div class="card-head"><div><p class="eyebrow">SPELIDEE</p><h2>${esc(team.name)}</h2></div></div><div class="tactic-list">${list.map(x=>`<button class="tactic-card ${x.id===t.id?'active':''}" data-select-tactic="${x.id}"><strong>${esc(x.name)}</strong><div class="muted tiny">${esc(x.formation)} · ${esc(x.phase||'')}</div></button>`).join('')}</div></aside><section class="card"><div class="card-head"><div><p class="eyebrow">${esc(t.phase||'TACTIEK')}</p><h2>${esc(t.name)}</h2><p class="muted small">${esc(t.formation||'')} · ${esc(t.description||'')}</p></div></div><div class="canvas-toolbar"><button class="tool-btn ${ui.tacticTool==='playerA'?'active':''}" data-tactic-tool="playerA">Speler groen</button><button class="tool-btn ${ui.tacticTool==='playerB'?'active':''}" data-tactic-tool="playerB">Tegenstander</button><button class="tool-btn ${ui.tacticTool==='cone'?'active':''}" data-tactic-tool="cone">Pion</button><button class="tool-btn ${ui.tacticTool==='ball'?'active':''}" data-tactic-tool="ball">Bal</button><button class="tool-btn ${ui.tacticTool==='arrow'?'active':''}" data-tactic-tool="arrow">Pijl</button><button class="tool-btn ${ui.tacticTool==='zone'?'active':''}" data-tactic-tool="zone">Zone</button><button class="tool-btn ${ui.tacticTool==='erase'?'active':''}" data-tactic-tool="erase">Wissen</button><button class="tool-btn" data-tactic-formation>Formatie op bord</button><button class="tool-btn" data-clear-tactic-board>Bord leeg</button></div><canvas id="tacticCanvas" width="680" height="1050" aria-label="Tactiekbord"></canvas><p class="muted tiny">Tik/klik om spelers, pionnen en bal te plaatsen. Voor een pijl of zone: kies beginpunt en daarna eindpunt. Wissen verwijdert het dichtstbijzijnde object.</p><h3 class="section-title">Coachafspraken</h3>${t.points?.length?`<ul class="coach-points">${t.points.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<div class="empty">Nog geen tactische coachpunten.</div>'}</section></div>`:`<div class="empty">Nog geen tactiek voor ${esc(team.name)}. Voeg bijvoorbeeld je 4-3-3 pressingorganisatie toe.</div>`}`}
function tacticForm(t={}){return `<div class="form-grid"><div class="field full"><label>Naam</label><input id="fTacName" class="input" value="${esc(t.name||'')}"></div><div class="field"><label>Team</label><select id="fTacTeam">${teamOptions(t.teamId||ui.teamId)}</select></div><div class="field"><label>Formatie</label><select id="fTacFormation">${formationOptions(t.formation||activeTeam()?.formation||'4-3-3')}</select></div><div class="field full"><label>Fase</label><input id="fTacPhase" class="input" placeholder="Basisorganisatie / pressing / opbouw" value="${esc(t.phase||'')}"></div><div class="field full"><label>Beschrijving</label><textarea id="fTacDesc">${esc(t.description||'')}</textarea></div><div class="field full"><label>Coachafspraken (1 per regel)</label><textarea id="fTacPoints">${esc((t.points||[]).join('\n'))}</textarea></div></div>`}
function editTactic(id){const t=id?tacticById(id):null;modal(t?'Tactiek bewerken':'Tactiek toevoegen',tacticForm(t||{}),()=>{const name=$('#fTacName').value.trim();if(!name){toast('Vul een naam in');return false}const obj=t||{id:uid('t'),board:{objects:[]}};Object.assign(obj,{name,teamId:$('#fTacTeam').value,formation:$('#fTacFormation').value,phase:$('#fTacPhase').value.trim(),description:$('#fTacDesc').value.trim(),points:$('#fTacPoints').value.split('\n').map(x=>x.trim()).filter(Boolean)});obj.board??={objects:[]};if(!t)state.tactics.push(obj);ui.teamId=obj.teamId;ui.tacticId=obj.id;return true})}
function drawPitchCanvas(){const c=$('#tacticCanvas'),t=tacticById(ui.tacticId);if(!c||!t)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#2d7e53';ctx.fillRect(0,0,w,h);ctx.strokeStyle='rgba(255,255,255,.78)';ctx.lineWidth=5;ctx.strokeRect(12,12,w-24,h-24);ctx.beginPath();ctx.moveTo(12,h/2);ctx.lineTo(w-12,h/2);ctx.stroke();ctx.beginPath();ctx.arc(w/2,h/2,92,0,Math.PI*2);ctx.stroke();ctx.strokeRect(w*.20,12,w*.60,h*.16);ctx.strokeRect(w*.20,h-h*.16-12,w*.60,h*.16);ctx.beginPath();ctx.arc(w/2,h/2,7,0,Math.PI*2);ctx.fillStyle='rgba(255,255,255,.85)';ctx.fill();for(const o of t.board.objects||[])drawTacticObject(ctx,o,w,h)}
function drawTacticObject(ctx,o,w,h){const x=o.x*w,y=o.y*h;if(o.type==='arrow'){const x2=o.x2*w,y2=o.y2*h;ctx.strokeStyle='#ffeb76';ctx.fillStyle='#ffeb76';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x2,y2);ctx.stroke();const a=Math.atan2(y2-y,x2-x),s=24;ctx.beginPath();ctx.moveTo(x2,y2);ctx.lineTo(x2-s*Math.cos(a-Math.PI/6),y2-s*Math.sin(a-Math.PI/6));ctx.lineTo(x2-s*Math.cos(a+Math.PI/6),y2-s*Math.sin(a+Math.PI/6));ctx.closePath();ctx.fill();return}if(o.type==='zone'){ctx.fillStyle='rgba(255,235,118,.18)';ctx.strokeStyle='rgba(255,235,118,.9)';ctx.lineWidth=4;ctx.fillRect(Math.min(x,o.x2*w),Math.min(y,o.y2*h),Math.abs(o.x2*w-x),Math.abs(o.y2*h-y));ctx.strokeRect(Math.min(x,o.x2*w),Math.min(y,o.y2*h),Math.abs(o.x2*w-x),Math.abs(o.y2*h-y));return}if(o.type==='cone'){ctx.fillStyle='#ffb04a';ctx.beginPath();ctx.moveTo(x,y-18);ctx.lineTo(x-16,y+16);ctx.lineTo(x+16,y+16);ctx.closePath();ctx.fill();return}if(o.type==='ball'){ctx.fillStyle='#fff';ctx.strokeStyle='#182d24';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,15,0,Math.PI*2);ctx.fill();ctx.stroke();return}ctx.fillStyle=o.type==='playerB'?'#d94747':'#f6faf7';ctx.strokeStyle=o.type==='playerB'?'#7e1f1f':'#123e2d';ctx.lineWidth=4;ctx.beginPath();ctx.arc(x,y,23,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle=o.type==='playerB'?'#fff':'#123e2d';ctx.font='bold 18px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(o.label||'',x,y)}
function canvasPoint(e,c){const r=c.getBoundingClientRect(),touch=e.touches?.[0]||e;return {x:Math.max(0,Math.min(1,(touch.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(touch.clientY-r.top)/r.height))}}
function tacticCanvasAction(e){e.preventDefault();const c=$('#tacticCanvas'),t=tacticById(ui.tacticId);if(!c||!t)return;const p=canvasPoint(e,c),objects=t.board.objects??=[];if(ui.tacticTool==='arrow'||ui.tacticTool==='zone'){if(!ui.arrowStart){ui.arrowStart=p;toast('Kies nu het eindpunt')}else{objects.push({id:uid('obj'),type:ui.tacticTool,x:ui.arrowStart.x,y:ui.arrowStart.y,x2:p.x,y2:p.y});ui.arrowStart=null;save({render:false});drawPitchCanvas()}return}if(ui.tacticTool==='erase'){let best=-1,dist=.08;objects.forEach((o,i)=>{const d=Math.hypot(o.x-p.x,o.y-p.y);if(d<dist){dist=d;best=i}});if(best>=0){objects.splice(best,1);save({render:false});drawPitchCanvas()}return}const count=objects.filter(o=>o.type===ui.tacticTool).length+1;objects.push({id:uid('obj'),type:ui.tacticTool,x:p.x,y:p.y,label:ui.tacticTool.startsWith('player')?String(count):''});save({render:false});drawPitchCanvas()}
function putFormationOnBoard(){const t=tacticById(ui.tacticId);if(!t)return;const slots=FORMATIONS[t.formation]||FORMATIONS['4-3-3'];t.board.objects=(t.board.objects||[]).filter(o=>o.type!=='playerA');slots.forEach((s,i)=>t.board.objects.push({id:uid('obj'),type:'playerA',x:s[2]/100,y:s[3]/100,label:s[1]}));save({render:false});drawPitchCanvas();toast('Formatie op tactiekbord gezet')}

function renderSeason(){const schedule=combinedSchedule(),months=[...new Set(schedule.map(e=>e.date.slice(0,7)))].sort();const around=[-1,0,1].map(off=>{const d=new Date(TODAY()+'T12:00:00');d.setMonth(d.getMonth()+off);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`});const calendars=[...new Set(around)].map(k=>renderMonthCalendar(k,schedule)).join('');return `<div class="toolbar"><div class="left"><button class="btn primary" data-add-season-item>＋ Seizoenitem</button><button class="btn secondary" data-edit-periodization>Weekritme bewerken</button></div><div class="right"><span class="muted small">${schedule.length} geplande items</span></div></div><div class="grid two"><section class="card"><div class="card-head"><div><p class="eyebrow">KALENDER</p><h2>Rond deze maand</h2></div></div>${calendars}</section><section class="card"><div class="card-head"><div><p class="eyebrow">PERIODISERING</p><h2>Weekritme</h2></div><button class="btn ghost small-btn" data-edit-periodization>Bewerk</button></div><p class="muted small">${esc(state.periodization.principles||'Pas belasting aan op wedstrijdafstand, beschikbaarheid en trainingsdoel.')}</p><div class="week-template">${(state.periodization.weeklyTemplate||[]).map(d=>`<div class="week-day"><strong>${esc(d.day)}</strong><span class="badge ${d.load==='Hoog'?'orange':d.load==='Laag'?'green':'blue'}">${esc(d.load)}</span><p class="small">${esc(d.focus)}</p></div>`).join('')}</div><div class="divider"></div><h3>Planning per maand</h3>${months.length?months.map(k=>`<div class="calendar-month"><strong>${monthLabel(k)}</strong>${schedule.filter(e=>e.date.startsWith(k)).map(seasonPlanningRow).join('')}</div>`).join(''):'<div class="empty">Nog geen seizoenitems.</div>'}</section></div>`}
function seasonPlanningRow(e){
  const custom=state.seasonItems.some(x=>x.id===e.id),d=new Date(e.date+'T12:00:00');
  const inner=`<div class="date-box"><strong>${d.getDate()}</strong><span>${d.toLocaleDateString('nl-NL',{month:'short'})}</span></div><div><strong>${esc(e.type==='Wedstrijd'?(e.opponent?`vs ${e.opponent}`:'Wedstrijd'):(e.title||e.type||'Activiteit'))}</strong><div class="event-meta"><span class="muted small">${fmtDate(e.date)} ${esc(e.startTime||'')}</span><span class="chip">${esc(e.type||'Activiteit')}</span></div></div>`;
  if(custom)return `<div class="schedule-row">${inner}<div class="row-actions"><button class="btn ghost small-btn" data-edit-season-item="${e.id}">Bewerk</button><button class="btn danger small-btn" data-delete-season-item="${e.id}">×</button></div></div>`;
  if(e.type==='Training')return `<button type="button" class="schedule-row schedule-link" data-open-schedule-training="${e.id}">${inner}<span class="badge green">Training</span></button>`;
  if(e.type==='Wedstrijd')return `<button type="button" class="schedule-row schedule-link" data-open-schedule-match="${e.id}">${inner}<span class="badge blue">Wedstrijd</span></button>`;
  return `<div class="schedule-row">${inner}<span class="badge">${esc(e.type||'Activiteit')}</span></div>`;
}
function periodizationForm(){const days=['Ma','Di','Wo','Do','Vr','Za','Zo'],byDay=Object.fromEntries((state.periodization.weeklyTemplate||[]).map(x=>[x.day,x]));return `<div class="form-grid"><div class="field full"><label>Periodiseringsprincipes</label><textarea id="fPeriodPrinciples">${esc(state.periodization.principles||'')}</textarea></div><div class="field full"><label>Standaard wedstrijddag</label><select id="fMatchDay">${['Maandag','Dinsdag','Woensdag','Donderdag','Vrijdag','Zaterdag','Zondag'].map(x=>`<option ${state.periodization.matchDay===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><h3>Weekritme</h3><div class="period-edit-grid">${days.map(day=>{const x=byDay[day]||{focus:'',load:'Laag'};return `<div class="period-edit-row"><strong>${day}</strong><input class="input" id="periodFocus-${day}" value="${esc(x.focus||'')}" placeholder="Focus"><select id="periodLoad-${day}">${['Laag','Middel','Hoog','Wedstrijd'].map(l=>`<option ${x.load===l?'selected':''}>${l}</option>`).join('')}</select></div>`}).join('')}</div></div></div>`}
function editPeriodization(){modal('Periodisering bewerken',periodizationForm(),()=>{state.periodization.principles=$('#fPeriodPrinciples').value.trim();state.periodization.matchDay=$('#fMatchDay').value;state.periodization.weeklyTemplate=['Ma','Di','Wo','Do','Vr','Za','Zo'].map(day=>({day,focus:$(`#periodFocus-${day}`).value.trim(),load:$(`#periodLoad-${day}`).value}));return true})}
