function editSeasonItem(id){const x=id?state.seasonItems.find(s=>s.id===id):null;modal(x?'Seizoenitem bewerken':'Seizoenitem toevoegen',seasonItemForm(x||{}),()=>{const date=$('#fSeasonDate').value,title=$('#fSeasonTitle').value.trim();if(!date||!title){toast('Vul datum en titel in');return false}const obj=x||{id:uid('si')};Object.assign(obj,{date,startTime:$('#fSeasonTime').value,teamId:$('#fSeasonTeam').value,type:$('#fSeasonType').value,title,notes:$('#fSeasonNotes').value.trim()});if(!x)state.seasonItems.push(obj);state.seasonItems.sort((a,b)=>a.date.localeCompare(b.date));return true})}
function renderMonthCalendar(key,schedule){const [y,m]=key.split('-').map(Number),first=new Date(y,m-1,1),last=new Date(y,m,0),start=(first.getDay()+6)%7;let cells=[];for(let i=0;i<start;i++)cells.push('<div class="calendar-day out"></div>');for(let d=1;d<=last.getDate();d++){const date=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`,events=schedule.filter(e=>e.date===date);cells.push(`<div class="calendar-day ${date===TODAY()?'today':''}"><div class="calendar-date">${d}</div>${events.map(e=>`<span class="calendar-event ${e.type==='Wedstrijd'?'match':''}">${esc(e.type==='Wedstrijd'?(e.opponent||'Wedstrijd'):(e.focus||'Training'))}</span>`).join('')}</div>`)}return `<div class="calendar-month"><h3 style="margin-bottom:8px;text-transform:capitalize">${monthLabel(key)}</h3><div class="calendar-grid">${['ma','di','wo','do','vr','za','zo'].map(x=>`<div class="calendar-head">${x}</div>`).join('')}${cells.join('')}</div></div>`}

function attendanceStatsForTrainings(playerId,trainings){
  const relevant=trainings.filter(t=>eventPlayerIds(t).includes(playerId));
  const filled=relevant.filter(t=>t.attendance?.[playerId]);
  if(!filled.length)return {pct:null,present:0,filled:0,relevant:relevant.length};
  const present=filled.filter(t=>presentStatus(t.attendance[playerId])).length;
  return {pct:Math.round(present/filled.length*100),present,filled:filled.length,relevant:relevant.length};
}
function teamAttendanceStatsForTrainings(trainings){
  let present=0,filled=0;
  trainings.forEach(t=>eventPlayerIds(t).forEach(pid=>{
    const status=t.attendance?.[pid];
    if(!status)return;
    filled++;
    if(presentStatus(status))present++;
  }));
  return {pct:filled?Math.round(present/filled*100):null,present,filled};
}
function renderStats(){
  const team=activeTeam();
  const players=playersForTeam(team.id);
  const allTrainings=state.trainings
    .filter(t=>t.teamId===team.id&&t.date<=TODAY())
    .sort((a,b)=>b.date.localeCompare(a.date));
  const recent4=allTrainings.slice(0,4);
  const teamAll=teamAttendanceStatsForTrainings(allTrainings);
  const teamRecent=teamAttendanceStatsForTrainings(recent4);
  const trainingData=players.map(p=>({
    p,
    all:attendanceStatsForTrainings(p.id,allTrainings),
    recent:attendanceStatsForTrainings(p.id,recent4)
  })).sort((a,b)=>(b.recent.pct??-1)-(a.recent.pct??-1)||(b.all.pct??-1)-(a.all.pct??-1));

  const matchData=players.map(p=>({p,m:matchTotals(p.id,team.id)})).sort((a,b)=>b.m.minutes-a.m.minutes);
  const scoredMatches=state.matches.filter(m=>m.teamId===team.id&&m.goalsFor!==''&&m.goalsAgainst!=='');
  const gf=scoredMatches.reduce((a,m)=>a+number(m.goalsFor),0),ga=scoredMatches.reduce((a,m)=>a+number(m.goalsAgainst),0);
  const recentLabel=recent4.length?recent4.slice().reverse().map(t=>fmtDate(t.date)).join(' · '):'Nog geen trainingen';

  return `<section class="stats-section">
    <div class="stats-section-heading"><div><p class="eyebrow">TRAININGEN</p><h2>Trainingsstatistieken</h2><p class="muted small">Alleen trainingen tellen mee voor aanwezigheid. Laatste 4: ${esc(recentLabel)}</p></div></div>
    <div class="grid kpis">
      <div class="card kpi"><span>Trainingen gespeeld</span><strong>${allTrainings.length}</strong><span>t/m vandaag</span></div>
      <div class="card kpi"><span>Opkomst geheel</span><strong>${teamAll.pct===null?'–':teamAll.pct+'%'}</strong><span>${teamAll.filled} ingevulde statussen</span></div>
      <div class="card kpi"><span>Opkomst laatste 4</span><strong>${teamRecent.pct===null?'–':teamRecent.pct+'%'}</strong><span>${recent4.length} training${recent4.length===1?'':'en'}</span></div>
      <div class="card kpi"><span>Spelers met data</span><strong>${trainingData.filter(x=>x.all.filled>0).length}</strong><span>van ${players.length} spelers</span></div>
    </div>
    <section class="card stats-detail-card">
      <div class="card-head"><div><p class="eyebrow">AANWEZIGHEID</p><h2>Per speler</h2></div></div>
      <div class="table-wrap"><table class="training-stats-table"><thead><tr><th>Speler</th><th>Geheel</th><th>Laatste 4</th><th>Aanwezig geheel</th><th>Laatste 4 ingevuld</th></tr></thead><tbody>${trainingData.map(x=>`<tr><td><button class="link-button" data-profile-player="${x.p.id}">${esc(x.p.name)}</button></td><td><strong>${x.all.pct===null?'–':x.all.pct+'%'}</strong></td><td><strong class="${x.recent.pct!==null&&x.recent.pct<75?'danger-text':''}">${x.recent.pct===null?'–':x.recent.pct+'%'}</strong></td><td>${x.all.present}/${x.all.filled||0}</td><td>${x.recent.filled}/${x.recent.relevant||recent4.length}</td></tr>`).join('')}</tbody></table></div>
    </section>
  </section>

  <section class="stats-section match-stats-section">
    <div class="stats-section-heading"><div><p class="eyebrow">WEDSTRIJDEN</p><h2>Wedstrijdstatistieken</h2><p class="muted small">Wedstrijdminuten, basisplaatsen, goals en assists staan los van trainingsaanwezigheid.</p></div></div>
    <div class="grid kpis">
      <div class="card kpi"><span>Wedstrijden met score</span><strong>${scoredMatches.length}</strong><span>${gf} voor · ${ga} tegen</span></div>
      <div class="card kpi"><span>Wedstrijdminuten</span><strong>${matchData.reduce((a,x)=>a+x.m.minutes,0)}</strong><span>geregistreerd</span></div>
      <div class="card kpi"><span>Goals spelers</span><strong>${matchData.reduce((a,x)=>a+x.m.goals,0)}</strong><span>geregistreerd</span></div>
      <div class="card kpi"><span>Assists spelers</span><strong>${matchData.reduce((a,x)=>a+x.m.assists,0)}</strong><span>geregistreerd</span></div>
    </div>
    <section class="card stats-detail-card"><div class="card-head"><div><p class="eyebrow">WEDSTRIJD</p><h2>Spelerstatistieken</h2></div></div><div class="table-wrap"><table><thead><tr><th>Speler</th><th>W</th><th>Basis</th><th>Min</th><th>G</th><th>A</th></tr></thead><tbody>${matchData.map(x=>`<tr><td><button class="link-button" data-profile-player="${x.p.id}">${esc(x.p.name)}</button></td><td>${x.m.games}</td><td>${x.m.starts}</td><td>${x.m.minutes}</td><td>${x.m.goals}</td><td>${x.m.assists}</td></tr>`).join('')}</tbody></table></div></section>
  </section>`;
}
function renderNotes(){const team=activeTeam(),q=ui.noteFilter.toLowerCase(),notes=state.coachNotes.filter(n=>(!n.teamId||n.teamId===team.id)&&(!q||[n.text,n.category,playerById(n.playerId)?.name||''].join(' ').toLowerCase().includes(q))).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `<div class="toolbar"><div class="left"><input id="noteSearch" class="input" placeholder="Zoek notities..." value="${esc(ui.noteFilter)}"></div><div class="right"><button class="btn primary" data-add-note>＋ Coachnotitie</button></div></div><section class="card"><div class="card-head"><div><p class="eyebrow">OBSERVATIES</p><h2>${esc(team.name)}</h2></div></div>${notes.length?notes.map(n=>`<div class="note-card"><div class="note-meta"><span class="badge">${fmtDate(n.date)}</span><span class="chip">${esc(n.category||'Algemeen')}</span>${n.playerId?`<button class="chip green" data-profile-player="${n.playerId}">${esc(playerById(n.playerId)?.name||'Speler')}</button>`:''}${n.eventId?`<span class="chip blue">${esc(eventType(eventById(n.eventId)))} ${fmtDate(eventById(n.eventId)?.date)}</span>`:''}</div><div>${nl2br(n.text)}</div><div class="row-actions" style="margin-top:8px"><button class="btn ghost small-btn" data-edit-note="${n.id}">Bewerk</button><button class="btn danger small-btn" data-delete-note="${n.id}">×</button></div></div>`).join(''):'<div class="empty">Nog geen coachnotities.</div>'}</section>`}
function noteForm(n={}){const events=combinedSchedule(ui.teamId).slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,80);return `<div class="form-grid"><div class="field"><label>Datum</label><input id="fNoteDate" class="input" type="date" value="${esc(n.date||TODAY())}"></div><div class="field"><label>Categorie</label><select id="fNoteCat">${['Algemeen','Training','Wedstrijd','Ontwikkeling','Gedrag/inzet','Tactiek','Gesprek'].map(x=>`<option ${n.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Speler (optioneel)</label><select id="fNotePlayer"><option value="">Geen speler</option>${playersForTeam(ui.teamId).map(p=>`<option value="${p.id}" ${n.playerId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Training/wedstrijd (optioneel)</label><select id="fNoteEvent"><option value="">Geen activiteit</option>${events.map(e=>`<option value="${e.id}" ${n.eventId===e.id?'selected':''}>${fmtDate(e.date)} · ${esc(e.type)}</option>`).join('')}</select></div><div class="field full"><label>Notitie</label><textarea id="fNoteText">${esc(n.text||'')}</textarea></div></div>`}
function editNote(id){const n=id?state.coachNotes.find(x=>x.id===id):null;modal(n?'Coachnotitie bewerken':'Coachnotitie toevoegen',noteForm(n||{}),()=>{const text=$('#fNoteText').value.trim();if(!text){toast('Vul een notitie in');return false}const obj=n||{id:uid('note')};Object.assign(obj,{date:$('#fNoteDate').value||TODAY(),teamId:ui.teamId,category:$('#fNoteCat').value,playerId:$('#fNotePlayer').value||null,eventId:$('#fNoteEvent').value||null,text});if(!n)state.coachNotes.push(obj);return true})}

function renderAssistant(){const answer=ui.assistantAnswer||'Stel een vraag over je team, aanwezigheid, trainingsplanning of wedstrijdevaluaties. Zonder externe AI-endpoint werkt de coachassistent lokaal met je appgegevens.';return `<div class="grid two"><section class="card"><div class="card-head"><div><p class="eyebrow">COACHASSISTENT</p><h2>Vraag je eigen appdata</h2></div><span class="badge ${state.ai.endpoint?'blue':'green'}">${state.ai.endpoint?'Endpoint':'Lokaal'}</span></div><div class="prompt-suggestions"><button class="prompt-chip" data-assistant-prompt="Welke spelers hebben de laagste trainingsopkomst?">Lage opkomst</button><button class="prompt-chip" data-assistant-prompt="Wat moet terugkomen in de volgende training op basis van de laatste wedstrijdevaluatie?">Volgende training</button><button class="prompt-chip" data-assistant-prompt="Maak een training gericht op hoge pressing voor mijn huidige groep.">Training pressing</button><button class="prompt-chip" data-assistant-prompt="Geef een kort overzicht van de wedstrijdminuten van mijn spelers.">Wedstrijdminuten</button></div><div class="field" style="margin-top:14px"><label>Vraag</label><textarea id="assistantPrompt" placeholder="Bijv. Welke 5 spelers hebben het meest aandacht nodig qua aanwezigheid?">${esc(ui.assistantPrompt||'')}</textarea></div><button class="btn primary" data-run-assistant>✦ Analyseer</button><p class="muted tiny">Een echte AI-koppeling kan via een beveiligde server/edge-function. Zet nooit een geheime API-sleutel rechtstreeks in deze GitHub Pages-code.</p></section><section class="card"><div class="card-head"><div><p class="eyebrow">ANTWOORD</p><h2>Coachadvies</h2></div></div><div class="assistant-box">${esc(answer)}</div></section></div>`}
function localAssistant(prompt){const q=prompt.toLowerCase(),team=activeTeam(),players=playersForTeam(team.id);if(/opkomst|aanwezig|afwezig/.test(q)){const d=players.map(p=>({name:p.name,pct:attendancePct(p.id,team.id)})).filter(x=>x.pct!==null).sort((a,b)=>a.pct-b.pct);return d.length?`Laagste trainingsopkomst binnen ${team.name}:\n${d.slice(0,8).map((x,i)=>`${i+1}. ${x.name}: ${x.pct}%`).join('\n')}\n\nGebruik dit als signaal; kijk daarnaast naar redenen zoals werk, school, blessure en vakantie.`:'Er is nog te weinig ingevulde aanwezigheidsdata.'}if(/wedstrijdmin|minuten|basis/.test(q)){const d=players.map(p=>({name:p.name,...matchTotals(p.id,team.id)})).sort((a,b)=>b.minutes-a.minutes);return `Wedstrijdminuten ${team.name}:\n${d.slice(0,12).map((x,i)=>`${i+1}. ${x.name}: ${x.minutes} min · ${x.starts} basis · ${x.goals}G/${x.assists}A`).join('\n')}` }if(/volgende training|evaluatie|wat moet terug/.test(q)){const m=state.matches.filter(x=>x.teamId===team.id&&x.date<=TODAY()).sort((a,b)=>b.date.localeCompare(a.date))[0];if(!m)return 'Er is nog geen eerdere wedstrijd om te analyseren.';return `Laatste wedstrijd: ${fmtDate(m.date)} tegen ${m.opponent||'tegenstander'}.\n\nVerbeterpunt: ${m.evaluation.improve||'niet ingevuld'}\nTerug laten komen: ${m.evaluation.nextTraining||'niet ingevuld'}\n\nAdvies: bouw de training op van herkenning in een kleine vorm naar een grotere wedstrijdvorm en gebruik dezelfde coachtaal als in je wedstrijdafspraken.`}if(/training|press|opbouw|omschakel|afwerk/.test(q)){const focus=/press/.test(q)?'Hoge pressing':/opbouw/.test(q)?'Opbouw':/omschakel/.test(q)?'Omschakeling':/afwerk/.test(q)?'Afwerken':'Wedstrijdgericht';const wanted=state.exercises.filter(e=>[e.name,e.description,...e.tags].join(' ').toLowerCase().includes(focus.toLowerCase().split(' ')[0])).slice(0,5);return `Voorstel voor focus “${focus}”:\n${(wanted.length?wanted:state.exercises.slice(0,5)).map((e,i)=>`${i+1}. ${e.name} (${e.duration} min)${e.coachPoints?.[0]?` — ${e.coachPoints[0]}`:''}`).join('\n')}\n\nOpen Trainingen → Trainingsgenerator om dit direct als plan op te slaan.`}return `Ik kan lokaal vooral antwoorden op aanwezigheid, spelersontwikkeling, wedstrijdminuten, wedstrijdevaluaties en trainingsopbouw.\n\nJe vraag was: “${prompt}”\n\nVoor vrijere analyse kun je in Instellingen een beveiligde AI-endpoint koppelen.`}
async function runAssistant(){const prompt=$('#assistantPrompt')?.value.trim();if(!prompt){toast('Vul een vraag in');return}ui.assistantPrompt=prompt;ui.assistantAnswer='Bezig met analyseren…';renderPage();if(state.ai.endpoint){try{const summary=buildCoachSummary();const r=await fetch(state.ai.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt,context:summary})});if(!r.ok)throw new Error('Endpoint gaf '+r.status);const data=await r.json();ui.assistantAnswer=data.answer||data.output||data.text||JSON.stringify(data);renderPage();return}catch(e){ui.assistantAnswer=`AI-endpoint niet bereikbaar (${e.message}). Daarom lokaal antwoord:\n\n${localAssistant(prompt)}`;renderPage();return}}ui.assistantAnswer=localAssistant(prompt);renderPage()}
function buildCoachSummary(){const team=activeTeam(),players=playersForTeam(team.id);return {team:{name:team.name,formation:team.formation},players:players.map(p=>({name:p.name,position:p.position,selection:p.selection,attendance:attendancePct(p.id,team.id),stats:matchTotals(p.id,team.id),goals:p.developmentGoals})),nextTraining:nextTraining(team.id),nextMatch:nextMatch(team.id),recentNotes:state.coachNotes.filter(n=>n.teamId===team.id).slice(-20),recentMatches:state.matches.filter(m=>m.teamId===team.id).slice(-5).map(m=>({date:m.date,opponent:m.opponent,score:[m.goalsFor,m.goalsAgainst],evaluation:m.evaluation,plan:m.plan}))}}

function renderSettings(){const s=getSync();return `<div class="grid two"><section class="card"><div class="card-head"><div><p class="eyebrow">CLUB & SEIZOEN</p><h2>Basisinstellingen</h2></div></div><div class="form-grid"><div class="field full"><label>Club</label><input id="setClub" class="input" value="${esc(state.club?.name||'')}"></div><div class="field"><label>Seizoen</label><input id="setSeason" class="input" value="${esc(state.team.season||'')}"></div><div class="field"><label>Standaard trainingstijd</label><input id="setTime" class="input" type="time" value="${esc(state.team.trainingTime||'20:00')}"></div><div class="field full"><label>Periodiseringsprincipes</label><textarea id="setPeriodization">${esc(state.periodization.principles||'')}</textarea></div><div class="field full"><label>Beveiligde AI-endpoint (optioneel)</label><input id="setAiEndpoint" class="input" placeholder="https://.../coach-ai" value="${esc(state.ai.endpoint||'')}"><p class="muted tiny">Gebruik een server/edge-function die zelf de geheime API-sleutel bewaart. Geen sleutel in deze app opslaan.</p></div></div><button class="btn primary" data-save-settings>Instellingen opslaan</button></section><section class="card"><div class="card-head"><div><p class="eyebrow">BACK-UP</p><h2>Gegevens veiligstellen</h2></div></div><p class="muted small">Exporteer regelmatig een JSON-back-up. Daarmee kun je alle teams, spelers, trainingen, aanwezigheid, oefeningen, tactieken en statistieken terugzetten.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" data-export>Back-up downloaden</button><button class="btn ghost" data-import>Back-up importeren</button><button class="btn danger" data-reset>Terug naar startdata</button></div></section></div><section class="card" style="margin-top:16px"><div class="card-head"><div><p class="eyebrow">VERSLEUTELDE SYNC</p><h2>iPhone · iPad · laptop</h2></div><span class="badge ${syncConfigured()?'green':''}">${syncConfigured()?'Ingesteld':'Secret key nodig'}</span></div><p class="muted small">Gebruik op ieder apparaat dezelfde Secret key. De overige synchronisatiegegevens zijn al ingesteld en blijven verborgen.</p><div class="form-grid"><div class="field full"><label>Secret key</label><input id="syncPass" class="input" type="password" autocomplete="off" placeholder="Voer de gedeelde Secret key in" value="${esc(s.pass||'')}"></div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" data-save-sync>Secret key opslaan</button><button class="btn ghost" data-push-sync ${syncConfigured()?'':'disabled'}>Upload nu</button><button class="btn ghost" data-pull-sync ${syncConfigured()?'':'disabled'}>Download nu</button></div><p id="syncStatus" class="muted small" style="margin-top:12px">${syncConfigured()?'Klaar voor versleutelde synchronisatie.':'Vul alleen de Secret key in om synchronisatie te activeren.'}</p></section>`}
function renderMore(){return `<div class="grid two"><section class="card"><div class="card-head"><div><p class="eyebrow">COACH</p><h2>Meer onderdelen</h2></div></div><div class="list">${[['matches','⚽','Wedstrijden'],['exercises','▦','Oefeningen'],['tactics','↗','Tactiekbord'],['season','▣','Seizoen'],['stats','▥','Statistieken'],['notes','✎','Coachnotities'],['documents','⌁','Bronnen'],['assistant','✦','Coachassistent'],['settings','⚙','Instellingen']].map(([p,i,l])=>`<button class="list-row more-link" data-go="${p}"><span>${i} ${l}</span><strong>›</strong></button>`).join('')}</div></section><section class="card"><div class="card-head"><div><p class="eyebrow">ACTIEF TEAM</p><h2>${esc(activeTeam()?.name||'')}</h2></div></div><p class="muted">Wissel bovenin de app van team. Elke training, wedstrijd en tactiek wordt aan een team gekoppeld, terwijl spelers in meerdere teams beschikbaar kunnen zijn.</p></section></div>`}

function modal(title,body,saveFn,opts={}){const d=$('#modal');$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;const b=$('#modalSave');b.textContent=opts.saveText||'Opslaan';b.onclick=e=>{e.preventDefault();if(opts.onSave){opts.onSave();return}const ok=saveFn?saveFn():true;if(ok===false)return;save({render:false});d.close();renderPage();opts.afterSave?.()};d.showModal()}
function closeModal(){const d=$('#modal');if(d?.open)d.close()}

function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`football-coach-backup-${TODAY()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
async function importBackup(file){try{const data=JSON.parse(await file.text());if(!Array.isArray(data.players)||!Array.isArray(data.trainings))throw new Error('Ongeldige back-up');state=data;normalize();save();toast('Back-up geïmporteerd')}catch(e){toast('Import mislukt: '+e.message)}}
function getSync(){let stored={};try{stored=JSON.parse(localStorage.getItem(SYNC_KEY)||'{}')}catch{}return {url:SYNC_PROJECT_URL,key:SYNC_PUBLIC_KEY,pass:stored.pass||''}}
function syncConfigured(){const s=getSync();return !!(s.url&&s.key&&s.pass)}
async function syncIdFromPass(pass){const raw=new TextEncoder().encode(`${SYNC_NAMESPACE}:${pass}`),hash=new Uint8Array(await crypto.subtle.digest('SHA-256',raw));return [...hash].map(b=>b.toString(16).padStart(2,'0')).join('')}
function bytesToB64(bytes){let s='';bytes.forEach(b=>s+=String.fromCharCode(b));return btoa(s)}function b64ToBytes(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
async function keyFromPass(pass,salt){const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:160000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encryptData(obj,pass){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await keyFromPass(pass,salt),plain=new TextEncoder().encode(JSON.stringify(obj)),cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain));return {v:1,salt:bytesToB64(salt),iv:bytesToB64(iv),data:bytesToB64(cipher)}}
async function decryptData(payload,pass){const salt=b64ToBytes(payload.salt),iv=b64ToBytes(payload.iv),key=await keyFromPass(pass,salt),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,b64ToBytes(payload.data));return JSON.parse(new TextDecoder().decode(plain))}
function syncStatus(msg){const el=$('#syncStatus');if(el)el.textContent=msg}
async function pushSync(silent=false){const s=getSync();if(!syncConfigured())return;try{syncStatus('Versleutelen en uploaden…');const id=await syncIdFromPass(s.pass),payload=await encryptData(state,s.pass);const r=await fetch(s.url.replace(/\/$/,'')+'/rest/v1/coach_data?on_conflict=id',{method:'POST',headers:{apikey:s.key,Authorization:'Bearer '+s.key,'Content-Type':'application/json',Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify([{id,payload,updated_at:new Date().toISOString()}])});if(!r.ok)throw new Error(await r.text());syncStatus('Gesynchroniseerd · '+new Date().toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'}));if(!silent)toast('Sync geüpload')}catch(e){syncStatus('Syncfout: '+e.message);if(!silent)toast('Sync mislukt')}}
async function pullSync(silent=false){const s=getSync();if(!syncConfigured())return;try{syncStatus('Gegevens ophalen…');const id=await syncIdFromPass(s.pass),r=await fetch(s.url.replace(/\/$/,'')+'/rest/v1/coach_data?id=eq.'+encodeURIComponent(id)+'&select=payload,updated_at',{headers:{apikey:s.key,Authorization:'Bearer '+s.key}});if(!r.ok)throw new Error(await r.text());const rows=await r.json();if(!rows.length){syncStatus('Nog geen clouddata voor deze Secret key. Upload dit apparaat eerst.');return}const remote=await decryptData(rows[0].payload,s.pass);state=remote;normalize();localStorage.setItem(STORAGE_KEY,JSON.stringify(state));renderPage();syncStatus('Clouddata opgehaald');if(!silent)toast('Clouddata opgehaald')}catch(e){syncStatus('Syncfout: '+e.message);if(!silent)toast('Ophalen mislukt')}}
async function initialSync(){if(!syncConfigured())return;try{const local=state.meta?.updatedAt||'',s=getSync(),id=await syncIdFromPass(s.pass),r=await fetch(s.url.replace(/\/$/,'')+'/rest/v1/coach_data?id=eq.'+encodeURIComponent(id)+'&select=payload,updated_at',{headers:{apikey:s.key,Authorization:'Bearer '+s.key}});if(!r.ok)return;const rows=await r.json();if(!rows.length)return;const remote=await decryptData(rows[0].payload,s.pass);if((remote.meta?.updatedAt||'')>local){state=remote;normalize();localStorage.setItem(STORAGE_KEY,JSON.stringify(state));renderPage();toast('Nieuwere clouddata geladen')}}catch{}}

function bindPage(){
  const ps=$('#playerSearch');if(ps)ps.oninput=e=>{ui.playerSearch=e.target.value;renderPage()};
  const es=$('#exerciseSearch');if(es)es.oninput=e=>{ui.exerciseSearch=e.target.value;renderPage()};
  const ec=$('#exerciseCategory');if(ec)ec.onchange=e=>{ui.exerciseCategory=e.target.value;renderPage()};
  const ns=$('#noteSearch');if(ns)ns.oninput=e=>{ui.noteFilter=e.target.value;renderPage()};
  const ae=$('#attendanceEvent');if(ae)ae.onchange=e=>{ui.attendanceId=e.target.value;renderPage()};
  $$('[data-attendance-player]').forEach(sel=>sel.onchange=e=>{const ev=eventById(ui.attendanceId);ev.attendance??={};ev.attendance[e.target.dataset.attendancePlayer]=e.target.value;save({render:false});const row=e.target.closest('tr');row?.classList.toggle('status-present',presentStatus(e.target.value));row?.classList.toggle('status-absent',absentStatus(e.target.value));toast('Aanwezigheid opgeslagen')});
  const ms=$('#matchSelect');if(ms)ms.onchange=e=>{ui.matchId=e.target.value;renderPage()};
  const mf=$('#matchFormation');if(mf)mf.onchange=e=>{const m=matchById(ui.matchId);m.formation=e.target.value;save()};
  $$('[data-match-check]').forEach(c=>c.onchange=e=>{const m=matchById(ui.matchId);m.checklist[e.target.dataset.matchCheck]=e.target.checked;save({render:false})});
  $$('[data-doc-candidate]').forEach(c=>c.onchange=e=>{const i=Number(e.target.dataset.docCandidate);ui.docCandidates[i].selected=e.target.checked;e.target.closest('.candidate-card')?.classList.toggle('selected',e.target.checked)});
  $$('[data-drag-player]').forEach(el=>{el.ondragstart=e=>{draggedPlayerId=e.currentTarget.dataset.dragPlayer;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggedPlayerId)}});
  $$('[data-lineup-slot]').forEach(slot=>{slot.ondragover=e=>{e.preventDefault();slot.classList.add('drag-over')};slot.ondragleave=()=>slot.classList.remove('drag-over');slot.ondrop=e=>{e.preventDefault();slot.classList.remove('drag-over');const pid=e.dataTransfer.getData('text/plain')||draggedPlayerId;if(pid)assignLineup(slot.dataset.matchId,slot.dataset.lineupSlot,pid)}});
  const canvas=$('#tacticCanvas');if(canvas){drawPitchCanvas();canvas.onpointerdown=tacticCanvasAction}
}

function handleClick(e){
  const b=e.target.closest('button');
  if(!b)return;

  if(b.dataset.page){setPage(b.dataset.page);return}
  if(b.dataset.go){setPage(b.dataset.go);return}
  if(b.dataset.teamTab){ui.teamId=b.dataset.teamTab;renderPage();return}
  if(b.dataset.openScheduleTraining){ui.trainingId=b.dataset.openScheduleTraining;return setPage('trainings')}
  if(b.dataset.openScheduleMatch){ui.matchId=b.dataset.openScheduleMatch;return setPage('matches')}

  if(b.hasAttribute('data-add-team'))return editTeam();
  if(b.dataset.editTeam)return editTeam(b.dataset.editTeam);

  if(b.hasAttribute('data-add-player'))return editPlayer();
  if(b.dataset.editPlayer)return editPlayer(b.dataset.editPlayer);
  if(b.dataset.profilePlayer)return showPlayerProfile(b.dataset.profilePlayer);
  if(b.dataset.archivePlayer){
    const p=playerById(b.dataset.archivePlayer);
    if(!p)return;
    if(confirm(`${p.name} uit de actieve selectie halen?\n\nDe historie van deze speler blijft volledig bewaard.`)){
      p.active=false;
      if(ui.page==='player'){
        ui.playerId=null;
        ui.page='players';
      }
      save();
      toast(`${p.name} is uit de actieve selectie gehaald`);
    }
    return;
  }

  if(b.dataset.attendance){ui.attendanceId=b.dataset.attendance;return setPage('attendance')}
  if(b.dataset.editEventSquad)return editEventSquad(b.dataset.editEventSquad);
  if(b.hasAttribute('data-all-present')){const ev=eventById(ui.attendanceId);eventPlayerIds(ev).forEach(id=>ev.attendance[id]='Aanwezig');return save()}
  if(b.hasAttribute('data-clear-attendance')){if(confirm('Alle aanwezigheid voor deze activiteit leegmaken?')){eventById(ui.attendanceId).attendance={};save()}return}

  if(b.hasAttribute('data-add-training'))return editTraining();
  if(b.dataset.editTraining)return editTraining(b.dataset.editTraining);
  if(b.dataset.trainingOpen){ui.trainingId=b.dataset.trainingOpen;return setPage('trainings')}
  if(b.dataset.selectTraining){ui.trainingId=b.dataset.selectTraining;return renderPage()}
  if(b.hasAttribute('data-add-plan-item'))return addPlanItem();
  if(b.dataset.editPlanItem)return editPlanItem(b.dataset.editPlanItem);
  if(b.dataset.planUp)return movePlanItem(b.dataset.planUp,-1);
  if(b.dataset.planDown)return movePlanItem(b.dataset.planDown,1);
  if(b.dataset.removePlanItem)return removePlanItem(b.dataset.removePlanItem);
  if(b.hasAttribute('data-generate')){ui.generatorPlan=null;return renderPage()}
  if(b.hasAttribute('data-run-generator'))return generateTrainingPlan();
  if(b.hasAttribute('data-save-generator'))return saveGenerator();
  if(b.hasAttribute('data-clear-generator')){ui.generatorPlan=null;return renderPage()}

  if(b.hasAttribute('data-add-exercise'))return editExercise();
  if(b.dataset.editExercise)return editExercise(b.dataset.editExercise);
  if(b.dataset.deleteExercise){if(confirm('Oefening verwijderen? Trainingsplannen met deze oefening houden mogelijk een ontbrekende verwijzing.')){state.exercises=state.exercises.filter(x=>x.id!==b.dataset.deleteExercise);save()}return}

  if(b.hasAttribute('data-pick-document')){$('#docFile').click();return}
  if(b.hasAttribute('data-doc-select-all')){ui.docCandidates.forEach(c=>c.selected=true);return renderPage()}
  if(b.hasAttribute('data-import-doc-candidates'))return importDocCandidates();
  if(b.dataset.editDocCandidate!==undefined)return editDocCandidate(Number(b.dataset.editDocCandidate));
  if(b.dataset.deleteDocument){if(confirm('Alleen de bronverwijzing verwijderen? De al geïmporteerde oefeningen blijven staan.')){state.documents=state.documents.filter(d=>d.id!==b.dataset.deleteDocument);save()}return}

  if(b.hasAttribute('data-add-match'))return editMatch();
  if(b.dataset.editMatch)return editMatch(b.dataset.editMatch);
  if(b.dataset.editMatchStat)return editMatchStat(b.dataset.editMatchStat);
  if(b.hasAttribute('data-edit-bench'))return editBenchSelection();if(b.dataset.toggleBench)return toggleBenchPlayer(b.dataset.toggleBench);if(b.dataset.lineupSlot)return chooseLineupPlayer(b.dataset.matchId,b.dataset.lineupSlot);
  if(b.hasAttribute('data-clear-lineup')){const m=matchById(ui.matchId);m.lineup={};m.checklist.lineup=false;return save()}
  if(b.hasAttribute('data-save-score')){const m=matchById(ui.matchId);m.goalsFor=$('#matchGoalsFor').value.trim();m.goalsAgainst=$('#matchGoalsAgainst').value.trim();return save()}
  if(b.dataset.trainingFromMatch)return trainingFromMatch(b.dataset.trainingFromMatch);

  if(b.hasAttribute('data-add-tactic'))return editTactic();
  if(b.dataset.editTactic)return editTactic(b.dataset.editTactic);
  if(b.dataset.selectTactic){ui.tacticId=b.dataset.selectTactic;return renderPage()}
  if(b.dataset.tacticTool){ui.tacticTool=b.dataset.tacticTool;ui.arrowStart=null;return renderPage()}
  if(b.hasAttribute('data-tactic-formation'))return putFormationOnBoard();
  if(b.hasAttribute('data-clear-tactic-board')){const t=tacticById(ui.tacticId);if(t&&confirm('Tactiekbord leegmaken?')){t.board.objects=[];save({render:false});drawPitchCanvas()}return}

  if(b.hasAttribute('data-edit-periodization'))return editPeriodization();
  if(b.hasAttribute('data-add-season-item'))return editSeasonItem();
  if(b.dataset.editSeasonItem)return editSeasonItem(b.dataset.editSeasonItem);
  if(b.dataset.deleteSeasonItem){if(confirm('Seizoenitem verwijderen?')){state.seasonItems=state.seasonItems.filter(x=>x.id!==b.dataset.deleteSeasonItem);save()}return}

  if(b.hasAttribute('data-add-note'))return editNote();
  if(b.dataset.editNote)return editNote(b.dataset.editNote);
  if(b.dataset.deleteNote){state.coachNotes=state.coachNotes.filter(n=>n.id!==b.dataset.deleteNote);return save()}

  if(b.dataset.assistantPrompt){ui.assistantPrompt=b.dataset.assistantPrompt;renderPage();const ta=$('#assistantPrompt');if(ta)ta.value=ui.assistantPrompt;return}
  if(b.hasAttribute('data-run-assistant'))return runAssistant();

  if(b.hasAttribute('data-save-settings')){state.club??={};state.club.name=$('#setClub').value.trim();state.team.season=$('#setSeason').value.trim();state.team.trainingTime=$('#setTime').value;state.periodization.principles=$('#setPeriodization').value.trim();state.ai.endpoint=$('#setAiEndpoint').value.trim();save();toast('Instellingen opgeslagen');return}
  if(b.hasAttribute('data-export'))return exportBackup();
  if(b.hasAttribute('data-import')){$('#importFile').click();return}
  if(b.hasAttribute('data-reset')){if(confirm('Alle lokale wijzigingen vervangen door de oorspronkelijke startdata? Maak eerst een back-up als je iets wilt bewaren.')){state=clone(window.STARTER_DATA);normalize();save();toast('Startdata teruggezet')}return}
  if(b.hasAttribute('data-save-sync')){const pass=$('#syncPass').value.trim();if(!pass){localStorage.removeItem(SYNC_KEY);renderPage();toast('Secret key verwijderd');return}localStorage.setItem(SYNC_KEY,JSON.stringify({pass}));renderPage();toast('Secret key opgeslagen');initialSync();return}
  if(b.hasAttribute('data-push-sync'))return pushSync();
  if(b.hasAttribute('data-pull-sync'))return pullSync();
}

document.addEventListener('click',handleClick);
$('#quickAdd').onclick=()=>{if(ui.page==='players')editPlayer();else if(ui.page==='matches')editMatch();else if(ui.page==='exercises')editExercise();else if(ui.page==='notes')editNote();else if(ui.page==='tactics')editTactic();else editTraining()};
$('#importFile').onchange=e=>{const f=e.target.files[0];if(f)importBackup(f);e.target.value=''};
$('#docFile').onchange=e=>{const f=e.target.files[0];if(f)handleDocument(f);e.target.value=''};
load();renderPage();initialSync();if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
